/**
 * Session analysis pipeline (FPA-CORE entry point).
 *
 *   frames ─► quality gate ─► rest reference (aligned median shape)
 *                           └► per task: align to rest ─► face frame ─► measure
 *                                        ─► peak-frame selection ─► median aggregate
 *          ─► ratios (affected / healthy) ─► scale mapping ─► result + warnings
 */
import { applySimilarity, dist, faceFrame, fitSimilarity, toFaceCoords, toPixels } from './geometry';
import { ALIGNMENT_CANDIDATES, ALIGNMENT_KEEP, CONTOURS, otherSide, outwardSign } from './landmarks';
import {
  browLevel,
  eyeAperture,
  irisDiameter,
  isMetricTask,
  lipCenter,
  measureLiveTask,
  measureTaskFrame,
  withMirrorClosure,
  midfaceLevel,
  midlineX,
  mouthCorner,
  taskSignal,
  type FrameTaskValues,
} from './measures';
import { stepConditions } from './conditions';
import { frontalizeSet } from './pose3d';
import { DEFAULT_QUALITY, assessFrame, type QualityThresholds } from './quality';
import { SCORING, computeScores, eyeEffectiveRatio, isScoredTask, restItems, synkinesisGrade, voluntaryGrade } from './scoring';
import { clamp, mean, median } from './stats';
import { ALGORITHM_ID, ALGORITHM_VERSION, SCORING_VERSION } from './version';
import {
  MOVEMENT_TASKS,
  type AnalysisResult,
  type FrameObservation,
  type FrameQuality,
  type LiveTaskId,
  type MovementTaskId,
  type QualityIssue,
  type RestMeasurement,
  type Side,
  type TaskMeasurement,
  type TaskQuality,
  type Vec2,
} from './types';

export const AGGREGATION = Object.freeze({
  /** Frames whose movement signal is ≥ this fraction of the peak are candidates. */
  peakRelative: 0.85,
  maxPeakFrames: 7,
  minValidFrames: { video: 5, photo: 1 },
  /** Median rest-frame deviation from the rest reference (face units). */
  maxRestJitter: 0.02,
  maxAlignmentResidual: 0.035,
  /** Mean adult horizontal visible iris diameter used for mm scaling. */
  irisDiameterMm: 11.7,
  /**
   * Smile: chin lowered by more than this (inter-pupil units, about 5 mm) = jaw opened (SRS-QC-009), read with the
   * head's nod undone in 3D (smileJawDrop). Provisional, from public faces in this pipeline: teeth-together smiles
   * (FRLL, 97 faces) reached 0.070 (95th percentile 0.059); RAVDESS happy speech with the jaw clearly open (MediaPipe
   * jawOpen above 0.5) had a median of 0.12 (10th percentile 0.078). In the image plane alone the chin follows head
   * nods (correlation −0.62 with the pitch change, 3D −0.22) and teeth-together smiles reached 0.107. Rejection logs
   * of the pilot set it.
   */
  maxJawDrop: 0.08,
});

export interface SessionInput {
  affectedSide: Side;
  mode: 'video' | 'photo';
  rest: readonly FrameObservation[];
  tasks: Partial<Record<MovementTaskId, readonly FrameObservation[]>>;
  quality?: QualityThresholds;
}

interface Gated {
  valid: { obs: FrameObservation; q: FrameQuality }[];
  total: number;
  issueCounts: Partial<Record<QualityIssue, number>>;
}

export function gate(frames: readonly FrameObservation[], th: QualityThresholds): Gated {
  const valid: Gated['valid'] = [];
  const issueCounts: Gated['issueCounts'] = {};
  for (const obs of frames) {
    const q = assessFrame(obs, th);
    if (q.ok) valid.push({ obs, q });
    for (const i of q.issues) issueCounts[i] = (issueCounts[i] ?? 0) + 1;
  }
  return { valid, total: frames.length, issueCounts };
}

/**
 * Similarity-aligns a whole landmark set onto `ref`: a least-trimmed fit that refits on the ALIGNMENT_KEEP
 * candidates agreeing best, so anchors moved by the expression itself (or lost by tracking) neither bias the
 * alignment nor count as head movement. `rms` is the residual of those kept anchors: rigid head motion the
 * similarity cannot remove (turning or nodding), not facial expression.
 */
export function alignTo(px: readonly Vec2[], ref: readonly Vec2[]): { pts: Vec2[]; rms: number } {
  const fit = (idx: readonly number[]) =>
    fitSimilarity(
      idx.map((i) => px[i]!),
      idx.map((i) => ref[i]!),
    );
  let keep: readonly number[] = ALIGNMENT_CANDIDATES;
  let T = fit(keep);
  for (let it = 0; it < 3; it++) {
    const err = (i: number) => dist(applySimilarity(T, px[i]!), ref[i]!);
    keep = [...ALIGNMENT_CANDIDATES].sort((a, b) => err(a) - err(b)).slice(0, ALIGNMENT_KEEP);
    T = fit(keep);
  }
  const pts = px.map((p) => applySimilarity(T, p));
  const rms = Math.sqrt(mean(keep.map((i) => dist(pts[i]!, ref[i]!) ** 2)));
  return { pts, rms };
}

export function medianShape(shapes: readonly (readonly Vec2[])[]): Vec2[] {
  const n = shapes[0]!.length;
  const out: Vec2[] = new Array(n);
  for (let i = 0; i < n; i++) out[i] = { x: median(shapes.map((s) => s[i]!.x)), y: median(shapes.map((s) => s[i]!.y)) };
  return out;
}

export function selectPeakFrames(signals: readonly number[], rel = AGGREGATION.peakRelative, maxN = AGGREGATION.maxPeakFrames): number[] {
  if (signals.length === 0) return [];
  const order = signals.map((_, i) => i).sort((a, b) => signals[b]! - signals[a]!);
  const peak = signals[order[0]!]!;
  if (peak <= 0) return order.slice(0, maxN);
  return order.filter((i) => signals[i]! >= peak * rel).slice(0, maxN);
}

function aggregate(values: readonly FrameTaskValues[]): FrameTaskValues {
  const med = (f: (v: FrameTaskValues) => number): number => median(values.map(f));
  const extras: Record<string, number> = {};
  for (const k of Object.keys(values[0]!.extras)) extras[k] = med((v) => v.extras[k]!);
  return {
    excursion: { right: med((v) => v.excursion.right), left: med((v) => v.excursion.left) },
    offTarget: { right: med((v) => v.offTarget.right), left: med((v) => v.offTarget.left) },
    extras,
  };
}

function taskQuality(g: Gated, usedFrames: readonly { obs: FrameObservation; q: FrameQuality }[], residual: number): TaskQuality {
  const used = usedFrames.map((u) => u.q);
  const conditions = stepConditions(usedFrames);
  return {
    framesTotal: g.total,
    framesValid: g.valid.length,
    framesUsed: used.length,
    issueCounts: g.issueCounts,
    medianAbsYaw: median(used.map((q) => Math.abs(q.pose.yaw))),
    medianAbsPitch: median(used.map((q) => Math.abs(q.pose.pitch))),
    medianAbsRoll: median(used.map((q) => Math.abs(q.pose.roll))),
    alignmentResidual: residual,
    ...(conditions ? { conditions } : {}),
  };
}

const round = (x: number, d: number): number => Math.round(x * 10 ** d) / 10 ** d;
const flatten = (pts: readonly Vec2[]): number[] => pts.flatMap((p) => [round(p.x, 2), round(p.y, 2)]);

function measureRest(F: readonly Vec2[], affected: Side): RestMeasurement {
  const healthy = otherSide(affected);
  const base = {
    eyeApertureRatio: eyeAperture(F, affected) / eyeAperture(F, healthy),
    browDrop: browLevel(F, affected) - browLevel(F, healthy),
    mouthCornerDrop: mouthCorner(F, affected).y - mouthCorner(F, healthy).y,
    midfaceDrop: midfaceLevel(F, affected) - midfaceLevel(F, healthy),
    mouthDeviation: (lipCenter(F).x - midlineX(F)) * outwardSign(healthy),
  };
  return { ...base, items: restItems(base) };
}

/** Which side moves less, from the log excursion ratio across tasks; null if ambiguous. */
/** Mean movement ratio between the sides that counts as a weaker side, and as a clearly weaker one. */
export const SIDE_WEAK_RATIO = 1.15;
export const SIDE_STRONG_RATIO = 1.5;

/**
 * Which side moves less, and how clearly (SRS-ALG-011): the mean log ratio of left to right over the scored tasks the
 * face performed. Weak from a 1.15× difference. Strong needs all of the following:
 * - at least 3 such tasks;
 * - a mean difference of 1.5× or more;
 * - all but at most one task agreeing (each by at least 1.15×).
 * A strong verdict is what a wrong side setting looks like: the healthy side measured as the paralysed one.
 */
export function sideEvidence(tasks: Partial<Record<MovementTaskId, TaskMeasurement>>): {
  side: Side | null;
  strength: 'strong' | 'weak' | null;
} {
  const logs: number[] = [];
  for (const t of Object.values(tasks)) {
    if (!isScoredTask(t.task)) continue;
    const max = Math.max(t.excursion.left, t.excursion.right);
    if (max < SCORING.minHealthyExcursion[t.task]) continue;
    const eps = 0.1 * SCORING.minHealthyExcursion[t.task];
    logs.push(Math.log((t.excursion.left + eps) / (t.excursion.right + eps)));
  }
  if (logs.length === 0) return { side: null, strength: null };
  const m = mean(logs);
  if (Math.abs(m) < Math.log(SIDE_WEAK_RATIO)) return { side: null, strength: null };
  const side: Side = m > 0 ? 'right' : 'left';
  const agree = logs.filter((l) => Math.sign(l) === Math.sign(m) && Math.abs(l) >= Math.log(SIDE_WEAK_RATIO)).length;
  const strong = logs.length >= 3 && Math.abs(m) >= Math.log(SIDE_STRONG_RATIO) && agree >= logs.length - 1;
  return { side, strength: strong ? 'strong' : 'weak' };
}

/** The side to recalculate with instead of the setting: only on a strong, contradicting verdict. */
export const autoSideTarget = (r: AnalysisResult): Side | null =>
  r.suggestedSideStrength === 'strong' && r.suggestedAffectedSide && r.suggestedAffectedSide !== r.affectedSide
    ? r.suggestedAffectedSide
    : null;

export function analyzeSession(input: SessionInput): AnalysisResult {
  const th = input.quality ?? DEFAULT_QUALITY;
  const minValid = AGGREGATION.minValidFrames[input.mode];
  const affected = input.affectedSide;
  const healthy = otherSide(affected);
  const result: AnalysisResult = {
    algorithm: { id: ALGORITHM_ID, version: ALGORITHM_VERSION, scoringVersion: SCORING_VERSION },
    status: 'failed',
    errors: [],
    warnings: [],
    affectedSide: affected,
    suggestedAffectedSide: null,
    mmPerUnit: null,
    restQuality: null,
    rest: null,
    tasks: {},
    scores: null,
    keyframes: null,
  };

  // ── Rest reference ────────────────────────────────────────────────────
  const restGate = gate(input.rest, th);
  if (restGate.valid.length < minValid) {
    result.errors.push({ code: 'REST_INSUFFICIENT', task: 'rest' });
    result.restQuality = taskQuality(restGate, restGate.valid, NaN);
    return result;
  }
  const restPxList = restGate.valid.map((v) => toPixels(v.obs));
  const aligned = restPxList.map((px) => alignTo(px, restPxList[0]!));
  const restPx = medianShape(aligned.map((a) => a.pts));
  const frame = faceFrame(restPx);
  const restF = toFaceCoords(frame, restPx);
  const restResidual = median(aligned.map((a) => a.rms)) / frame.unitPx;
  result.restQuality = taskQuality(restGate, restGate.valid, restResidual);

  // Rest stability: how far individual rest frames deviate from the median shape.
  if (restPxList.length > 1) {
    const jitter = median(aligned.map((a) => mean([33, 263, 61, 291, 105, 334, 159, 386].map((i) => dist(a.pts[i]!, restPx[i]!)))));
    if (jitter / frame.unitPx > AGGREGATION.maxRestJitter) result.warnings.push({ code: 'REST_UNSTABLE', task: 'rest' });
  }
  const bs = restGate.valid.map((v) => v.obs.blendshapes).filter((b): b is Record<string, number> => !!b);
  const eyesShut = eyeAperture(restF, 'left') < 0.06 && eyeAperture(restF, 'right') < 0.06;
  const expressive =
    bs.length > 0 &&
    (mean(bs.map((b) => b.jawOpen ?? 0)) > 0.25 || mean(bs.map((b) => ((b.mouthSmileLeft ?? 0) + (b.mouthSmileRight ?? 0)) / 2)) > 0.35);
  if (eyesShut || expressive) result.warnings.push({ code: 'REST_NOT_NEUTRAL', task: 'rest' });

  result.rest = measureRest(restF, affected);

  if (restF.length >= 478) {
    const irisD = (irisDiameter(restF, 'left') + irisDiameter(restF, 'right')) / 2;
    if (irisD >= 0.12 && irisD <= 0.3) result.mmPerUnit = AGGREGATION.irisDiameterMm / irisD;
  }
  if (result.mmPerUnit === null) result.warnings.push({ code: 'NO_IRIS_SCALE' });

  const keyTasks: Partial<Record<MovementTaskId, number[]>> = {};

  // ── Movement tasks ────────────────────────────────────────────────────
  for (const task of MOVEMENT_TASKS) {
    const frames = input.tasks[task];
    const g = gate(frames ?? [], th);
    if (g.valid.length < minValid) {
      result.errors.push({ code: 'TASK_INSUFFICIENT', task });
      continue;
    }
    const per = g.valid.map(({ obs, q }) => {
      const { pts, rms } = alignTo(toPixels(obs), restPx);
      const raw = measureTaskFrame(task, restF, toFaceCoords(frame, pts));
      const vals = task === 'eyeClose' ? withMirrorClosure(raw, obs, restF) : raw;
      return { vals, signal: taskSignal(vals), rms: rms / frame.unitPx, q, pts, obs };
    });
    const idx = selectPeakFrames(per.map((p) => p.signal));
    const sel = idx.map((i) => per[i]!);
    const agg = aggregate(sel.map((s) => s.vals));
    const medSignal = median(sel.map((s) => s.signal));
    const rep = sel.reduce((b, s) => (Math.abs(s.signal - medSignal) < Math.abs(b.signal - medSignal) ? s : b));
    keyTasks[task] = flatten(rep.pts);

    const excAff = agg.excursion[affected];
    const excHealthy = agg.excursion[healthy];
    const ratio = excHealthy > 1e-9 ? clamp(excAff / excHealthy, 0, 2) : 0;
    const reliable = excHealthy >= SCORING.minHealthyExcursion[task];
    const synkinesisIndex = Math.max(0, agg.offTarget[affected] - agg.offTarget[healthy]);
    const residual = median(sel.map((s) => s.rms));
    const mm = result.mmPerUnit;
    // Smile: the jaw check on the same rest frame and frames as the live check after the step (SRS-QC-009); it
    // replaces the per-frame chin drop read in the image plane.
    const extras = { ...agg.extras };
    const jaw =
      task === 'smile'
        ? smileJawDrop(
            restGate.valid[0]!.obs,
            g.valid.map((v) => v.obs),
            th,
          )
        : null;
    if (task === 'smile') {
      delete extras.jawDrop;
      if (jaw) extras.jawDrop = jaw.drop;
    }

    result.tasks[task] = {
      task,
      excursion: agg.excursion,
      ...(mm !== null && isMetricTask(task) ? { excursionMm: { right: agg.excursion.right * mm, left: agg.excursion.left * mm } } : {}),
      ratio,
      offTarget: agg.offTarget,
      synkinesisIndex,
      grade: voluntaryGrade(ratio),
      synkinesisGrade: synkinesisGrade(task, synkinesisIndex),
      reliable,
      extras,
      quality: taskQuality(
        g,
        sel.map((s) => ({ obs: s.obs, q: s.q })),
        residual,
      ),
    };
    if (!reliable) result.warnings.push({ code: 'LOW_EFFORT', task });
    if (residual > AGGREGATION.maxAlignmentResidual) result.warnings.push({ code: 'HIGH_ALIGNMENT_RESIDUAL', task });
    if (jaw && jaw.drop > AGGREGATION.maxJawDrop) result.warnings.push({ code: 'JAW_OPEN', task });
  }

  result.keyframes = { width: input.rest[0]!.width, height: input.rest[0]!.height, rest: flatten(restPx), tasks: keyTasks };
  const ev = sideEvidence(result.tasks);
  result.suggestedAffectedSide = ev.side;
  result.suggestedSideStrength = ev.strength;
  if (result.suggestedAffectedSide && result.suggestedAffectedSide !== affected) {
    result.warnings.push({ code: 'SIDE_MISMATCH' });
  }

  const all = MOVEMENT_TASKS.filter(isScoredTask).every((t) => result.tasks[t]?.reliable);
  result.status = all ? 'complete' : 'incomplete';
  // SC-0.3.0: the eye's grade follows its effective ratio (capped by the open lid gap), as in the scores.
  const eye = result.tasks.eyeClose;
  if (eye) eye.grade = voluntaryGrade(eyeEffectiveRatio(eye, affected, result.mmPerUnit));
  if (all) result.scores = computeScores(result.rest, result.tasks as Parameters<typeof computeScores>[1], affected, result.mmPerUnit);
  return result;
}

// ── Live measurement (exercise biofeedback) ─────────────────────────────

export interface RestReference {
  px: Vec2[];
  face: Vec2[];
  frame: ReturnType<typeof faceFrame>;
}

/** Builds a rest reference from neutral frames (quality-gated, aligned median). */
export function buildRestReference(frames: readonly FrameObservation[], th: QualityThresholds = DEFAULT_QUALITY): RestReference | null {
  const valid = frames.filter((o) => assessFrame(o, th).ok).map(toPixels);
  if (valid.length < 3) return null;
  const px = medianShape(valid.map((p) => alignTo(p, valid[0]!).pts));
  const frame = faceFrame(px);
  return { px, frame, face: toFaceCoords(frame, px) };
}

/** Measures one live frame against a rest reference; null if the frame fails the quality gate. */
export function measureLive(
  task: LiveTaskId,
  ref: RestReference,
  obs: FrameObservation,
  th: QualityThresholds = DEFAULT_QUALITY,
): FrameTaskValues | null {
  if (!assessFrame(obs, th).ok) return null;
  const { pts } = alignTo(toPixels(obs), ref.px);
  return measureLiveTask(task, ref.face, toFaceCoords(ref.frame, pts));
}

/**
 * The rest reference drawn on a live frame (exercise guide, SRS-RHB-015): the reference points, plus any extra points
 * given in the reference's pixel space (targets), mapped into the live image by the same robust similarity the
 * measurement uses, reversed. `live` is the frame's own points. Null without a face.
 */
export function restOnLive(
  ref: RestReference,
  obs: FrameObservation,
  extra: readonly Vec2[] = [],
): { rest: Vec2[]; extra: Vec2[]; live: Vec2[] } | null {
  if (obs.landmarks.length < 468 * 3) return null;
  const live = toPixels(obs);
  const { pts } = alignTo([...ref.px, ...extra], live);
  return { rest: pts.slice(0, ref.px.length), extra: pts.slice(ref.px.length), live };
}

/**
 * The jaw check of the smile (SRS-QC-009), after the step and in the analysis alike: the median chin drop of the
 * (up to 5) frames with the strongest smile against one rest frame, with the head's turn and nod between them undone
 * in 3D first (pose3d frontalizeSet; in the image plane a nod of about 5° moves the chin as far as the limit). Returns
 * those frames (as given, strongest first), or null without a usable rest frame or smile frame. Above
 * AGGREGATION.maxJawDrop the step is retaken with the teeth together.
 */
export function smileJawDrop(
  rest: FrameObservation | null | undefined,
  frames: readonly FrameObservation[],
  th: QualityThresholds = DEFAULT_QUALITY,
): { drop: number; frames: FrameObservation[] } | null {
  const hasFace = (o: FrameObservation) => o.landmarks.length >= 468 * 3;
  if (!rest || !hasFace(rest)) return null;
  const given = frames.filter(hasFace);
  const f = frontalizeSet(rest, given);
  const ref = buildRestReference([f.rest, f.rest, f.rest], th);
  if (!ref) return null;
  const top = f.frames
    .map((o, i) => ({ o: given[i]!, v: measureLive('smile', ref, o, th) }))
    .filter((x): x is { o: FrameObservation; v: FrameTaskValues } => x.v !== null)
    .sort((x, y) => taskSignal(y.v) - taskSignal(x.v))
    .slice(0, 5);
  return top.length ? { drop: median(top.map((x) => x.v.extras.jawDrop ?? 0)), frames: top.map((x) => x.o) } : null;
}

const EXPRESSIVE = [
  ...new Set([...CONTOURS.lipsOuter!, ...CONTOURS.rightEye!, ...CONTOURS.leftEye!, ...CONTOURS.rightBrow!, ...CONTOURS.leftBrow!]),
];

/**
 * How much the face is expressing in one frame, whatever the expression: mean displacement (face units) of the
 * lips, eyes and brows from the rest reference after alignment. Picks the frame kept as a step's photo.
 */
export function expressionMagnitude(ref: RestReference, obs: FrameObservation, th: QualityThresholds = DEFAULT_QUALITY): number | null {
  if (!assessFrame(obs, th).ok) return null;
  const face = toFaceCoords(ref.frame, alignTo(toPixels(obs), ref.px).pts);
  return mean(EXPRESSIVE.map((i) => dist(face[i]!, ref.face[i]!)));
}

/** Tasks the user should repeat (missing or not performed with the healthy side). */
export function tasksNeedingRetry(r: AnalysisResult): MovementTaskId[] {
  return MOVEMENT_TASKS.filter((t) => isScoredTask(t) && (!r.tasks[t] || !r.tasks[t]!.reliable));
}
