/**
 * Capture conditions of an assessment (face size in the frame, head pose),
 * derived from stored keyframes and quality data, and their comparison with
 * a previous assessment. Movement ratios are self-normalising, but mm values
 * and the eye/mouth appearance still shift when distance or angle change, so
 * sessions are only comparable under similar conditions.
 */
import { median } from './stats';
import type { AnalysisResult, FrameObservation, FrameQuality, StepConditions } from './types';

export interface CaptureConditions {
  /** Face width (temple to temple) as a fraction of the image width. */
  faceSize: number;
  yaw: number;
  pitch: number;
  roll: number;
}

/** Landmarks at the left/right face sides (temples). */
const SIDES = [127, 356] as const;

export function captureConditions(a: AnalysisResult | null | undefined): CaptureConditions | null {
  const k = a?.keyframes;
  const q = a?.restQuality;
  if (!k || !q || k.rest.length < 2 * 478 || !k.width) return null;
  const [i, j] = SIDES;
  const w = Math.hypot(k.rest[2 * i]! - k.rest[2 * j]!, k.rest[2 * i + 1]! - k.rest[2 * j + 1]!);
  return { faceSize: w / k.width, yaw: q.medianAbsYaw, pitch: q.medianAbsPitch, roll: q.medianAbsRoll };
}

export type ConditionIssue = 'CLOSER' | 'FARTHER' | 'YAW' | 'PITCH' | 'ROLL';

/** yawDeg is below the 5° capture gate (DEFAULT_QUALITY), otherwise a yaw change could never be flagged. */
export const CONDITION_LIMITS = { sizeRatio: 0.15, angleDeg: 5, yawDeg: 3 } as const;

/** Differences large enough to matter for comparing two sessions (empty = comparable). */
export function compareConditions(cur: CaptureConditions, prev: CaptureConditions): ConditionIssue[] {
  const out: ConditionIssue[] = [];
  const r = cur.faceSize / prev.faceSize;
  if (r > 1 + CONDITION_LIMITS.sizeRatio) out.push('CLOSER');
  else if (r < 1 / (1 + CONDITION_LIMITS.sizeRatio)) out.push('FARTHER');
  if (Math.abs(cur.yaw - prev.yaw) > CONDITION_LIMITS.yawDeg) out.push('YAW');
  if (Math.abs(cur.pitch - prev.pitch) > CONDITION_LIMITS.angleDeg) out.push('PITCH');
  if (Math.abs(cur.roll - prev.roll) > CONDITION_LIMITS.angleDeg) out.push('ROLL');
  return out;
}

/** Face width (temple to temple) as a fraction of the image width, from a live frame (normalised landmarks). */
export function liveFaceSize(obs: FrameObservation): number | null {
  const lm = obs.landmarks;
  const [i, j] = SIDES;
  if (lm.length < 3 * 478 || !obs.width) return null;
  const dx = (lm[3 * i]! - lm[3 * j]!) * obs.width;
  const dy = (lm[3 * i + 1]! - lm[3 * j + 1]!) * obs.height;
  return Math.hypot(dx, dy) / obs.width;
}

export type PlacementHint = 'ok' | 'closer' | 'farther';

/**
 * Live guidance to reproduce the previous session's distance: 'closer' = the face is larger than last time
 * (move the phone back), 'farther' = smaller (move closer). Same limit as compareConditions.
 */
export function placementHint(liveSize: number, prev: CaptureConditions): PlacementHint {
  const r = liveSize / prev.faceSize;
  if (r > 1 + CONDITION_LIMITS.sizeRatio) return 'closer';
  if (r < 1 / (1 + CONDITION_LIMITS.sizeRatio)) return 'farther';
  return 'ok';
}

/**
 * Capture conditions of the frames a step used (SRS-QC-010): medians of the face position and size in the image, the
 * face light and its balance, and, for tracked frames, the share of points kept and the face crop's sharpness.
 */
export function stepConditions(used: readonly { obs: FrameObservation; q: FrameQuality }[]): StepConditions | undefined {
  const withFace = used.filter((u) => u.obs.landmarks.length >= 468 * 3 && u.obs.width > 0 && u.obs.height > 0);
  if (withFace.length === 0) return undefined;
  const box = withFace.map(({ obs }) => {
    let x0 = 1;
    let y0 = 1;
    let x1 = 0;
    let y1 = 0;
    for (let i = 0; i < 468; i++) {
      const x = obs.landmarks[3 * i]!;
      const y = obs.landmarks[3 * i + 1]!;
      x0 = Math.min(x0, x);
      x1 = Math.max(x1, x);
      y0 = Math.min(y0, y);
      y1 = Math.max(y1, y);
    }
    return { cx: (x0 + x1) / 2 - 0.5, cy: (y0 + y1) / 2 - 0.5 };
  });
  const pick = <T>(f: (o: FrameObservation) => T | undefined) => withFace.flatMap(({ obs }) => (f(obs) === undefined ? [] : [f(obs)!]));
  const lum = pick((o) => (o.luminance?.horiz === undefined ? undefined : o.luminance));
  const kept = pick((o) => o.trackKept);
  const sh = pick((o) => o.sharpness);
  return {
    offsetX: median(box.map((b) => b.cx)),
    offsetY: median(box.map((b) => b.cy)),
    faceWidth: median(withFace.map(({ obs }) => liveFaceSize(obs) ?? 0)),
    eyePx: median(withFace.map(({ q }) => q.eyeDistancePx)),
    ...(lum.length
      ? {
          light: {
            mean: median(lum.map((l) => l.mean)),
            horiz: median(lum.map((l) => l.horiz!)),
            vert: median(lum.map((l) => l.vert ?? 0)),
          },
        }
      : {}),
    ...(kept.length ? { trackKept: median(kept) } : {}),
    ...(sh.length ? { sharp: median(sh.map((s) => s.sharp)), noise: median(sh.map((s) => s.noise)) } : {}),
  };
}

/**
 * Plain limits for the quality summary. Light: the guard value of the lighting test (docs/12 §5: 0.12 catches 23 % of
 * the harmful photos and blocks no clean one). Tracking: public photo sets kept a median 0.84 of the points (10th
 * percentile 0.68, 2026-10-13), so 0.6 flags only the clearly poor steps. Tracking and position are provisional, to
 * be set again from the pilot's phone recordings.
 */
export const CONDITION_NOTE_LIMITS = { lightSide: 0.12, trackKept: 0.6, offset: 0.15 } as const;

/** The face side that is brighter, in the patient's terms (the image's right half is the patient's left side). */
export const brighterSide = (horiz: number): 'left' | 'right' => (horiz > 0 ? 'left' : 'right');

/**
 * Short warnings about the capture of one assessment (Korean, for the results screen; empty = nothing to note):
 * one-sided light (and whether the affected side was the darker one), poorly tracked steps, an off-centre face.
 */
export function conditionNotes(a: AnalysisResult, stepLabel: (step: string) => string): string[] {
  const steps = [['rest', a.restQuality] as const, ...Object.entries(a.tasks).map(([t, m]) => [t, m?.quality ?? null] as const)].flatMap(
    ([t, q]) => (q?.conditions ? [{ t, c: q.conditions }] : []),
  );
  const out: string[] = [];
  const L = CONDITION_NOTE_LIMITS;
  const lit = steps.filter((s) => s.c.light && Math.abs(s.c.light.horiz) > L.lightSide);
  if (lit.length) {
    const worst = lit.reduce((b, s) => (Math.abs(s.c.light!.horiz) > Math.abs(b.c.light!.horiz) ? s : b));
    const side = brighterSide(worst.c.light!.horiz);
    const pct = Math.round(Math.abs(worst.c.light!.horiz) * 100);
    out.push(
      `빛이 한쪽에서 왔어요: ${side === 'right' ? '오른쪽' : '왼쪽'} 얼굴이 ${pct}% 밝아요` +
        `${side === a.affectedSide ? '' : ' (마비 쪽이 어두워 움직임이 덜 보일 수 있어요)'}. 창이나 조명을 정면에 두세요.`,
    );
  }
  const poor = steps.filter((s) => s.c.trackKept !== undefined && s.c.trackKept < L.trackKept);
  if (poor.length)
    out.push(
      `점 추적이 잘 안 된 단계: ${poor.map((s) => `${stepLabel(s.t)} ${Math.round(s.c.trackKept! * 100)}%`).join(', ')}. 흔들리지 않게, 밝은 곳에서 찍으면 좋아요.`,
    );
  const off = Math.max(0, ...steps.map((s) => Math.hypot(s.c.offsetX, s.c.offsetY)));
  if (off > L.offset) out.push(`얼굴이 화면 가운데서 ${Math.round(off * 100)}% 벗어났어요. 얼굴을 가운데 두세요.`);
  return out;
}
