/**
 * Which assessment movement a photo or video frame shows (FPA-EXPR). Used when a patient or clinician uploads
 * existing photos/videos instead of recording the guided assessment: every image is labelled rest, one of the five
 * movements, or 'other' (talking, jaw open…), so the right images reach the right task. The user can always
 * correct the label; the analysis itself is the unchanged FPA-GEOM.
 *
 * Evidence, all taken from the STRONGER side of the face so that a palsied half does not hide the movement the
 * healthy half performs:
 *  - blendshapes of the landmark model — as the change from the person's rest photo when there is one, otherwise raw;
 *  - geometric excursion against the rest photo (the assessment's own measures).
 * A small linear (softmax) model over these features makes the call; its weights are fitted by
 * tools/eval/fit_expression.py on the evaluation datasets and live in expressionModel.ts.
 * Pure and deterministic like the rest of core/.
 */
import { buildRestReference, expressionMagnitude, measureLive, type RestReference } from './analyze';
import { EXPRESSION_MODEL } from './expressionModel';
import type { QualityThresholds } from './quality';
import { MOVEMENT_TASKS, type FrameObservation, type MovementTaskId, type TaskId } from './types';

export const EXPRESSION_ALGORITHM = { id: 'FPA-EXPR', version: '0.1.0' } as const;

export type ExpressionLabel = TaskId | 'other';
export const EXPRESSION_LABELS: readonly ExpressionLabel[] = ['rest', ...MOVEMENT_TASKS, 'other'];
/** Labels the model scores ('other' is decided by a rule on top). */
export const MODEL_LABELS: readonly TaskId[] = ['rest', ...MOVEMENT_TASKS];

/** Blendshape channels, stronger side (max over left/right names). noseSneer/cheekSquint never fire in this model. */
export const BLEND_CHANNELS = {
  brow: ['browInnerUp', 'browOuterUpLeft', 'browOuterUpRight'],
  eye: ['eyeBlinkLeft', 'eyeBlinkRight'],
  smile: ['mouthSmileLeft', 'mouthSmileRight'],
  upperLip: ['mouthUpperUpLeft', 'mouthUpperUpRight'],
  pucker: ['mouthPucker'],
  funnel: ['mouthFunnel'],
  jaw: ['jawOpen'],
  squint: ['eyeSquintLeft', 'eyeSquintRight'],
  browDown: ['browDownLeft', 'browDownRight'],
  wide: ['eyeWideLeft', 'eyeWideRight'],
  stretch: ['mouthStretchLeft', 'mouthStretchRight'],
} as const;
export type BlendChannel = keyof typeof BLEND_CHANNELS;
const CHANNELS = Object.keys(BLEND_CHANNELS) as BlendChannel[];

export interface ExpressionFeatures {
  /** Raw blendshape channels (null when the landmarker gave none). */
  bs: Record<BlendChannel, number> | null;
  /** Change from the rest photo's blendshapes: per name expr − rest, then the stronger side. */
  bsDelta: Record<BlendChannel, number> | null;
  /** Stronger-side excursion against the rest reference, as a fraction of a typical full healthy movement. */
  geo: Record<MovementTaskId, number> | null;
  /** Mean displacement of lips, eyes and brows from the rest reference (face units). */
  magnitude: number | null;
}

/** Wide limits: recognition must work on photos the assessment gate would reject (the gate still reports them). */
export const RELAXED_QUALITY: Readonly<QualityThresholds> = Object.freeze({
  maxYawDeg: 35,
  maxPitchDeg: 35,
  maxRollDeg: 45,
  minEyeDistanceFrac: 0,
  minEyeDistancePx: 8,
  edgeMargin: -1,
  minLuminance: 0,
  maxLuminance: 256,
  maxLuminanceAsymmetry: 1,
});

/** Typical full excursion of a healthy side (face units; closure fraction for the eye): puts the five tasks on one scale. */
export const FULL_EXCURSION: Readonly<Record<MovementTaskId, number>> = Object.freeze({
  brow: 0.08,
  eyeClose: 0.9,
  smile: 0.1,
  snarl: 0.04,
  pucker: 0.08,
});

/** Landmark-only fallback: below this strongest-task strength the frame is rest. */
export const GEO_REST_BELOW = 0.35;

/** Jaw opening (raw, or change from rest) above which a frame without a task movement is 'other' (talking, yawning). */
export const OTHER_JAW = { raw: 0.35, delta: 0.25 } as const;

function channels(b: Record<string, number>, rest?: Record<string, number>): Record<BlendChannel, number> {
  const o = {} as Record<BlendChannel, number>;
  for (const c of CHANNELS) o[c] = Math.max(...BLEND_CHANNELS[c].map((k) => (b[k] ?? 0) - (rest ? (rest[k] ?? 0) : 0)));
  return o;
}

/** A rest reference from one rest observation (relaxed gate), or null. */
export function restReferenceFrom(obs: FrameObservation): RestReference | null {
  return buildRestReference([obs, obs, obs], RELAXED_QUALITY);
}

export interface RestContext {
  ref: RestReference;
  blendshapes?: Record<string, number>;
}

/** A rest context from the person's rest observation, or null without a face. */
export function restContext(obs: FrameObservation): RestContext | null {
  const ref = restReferenceFrom(obs);
  return ref ? { ref, ...(obs.blendshapes ? { blendshapes: obs.blendshapes } : {}) } : null;
}

export function expressionFeatures(obs: FrameObservation, rest?: RestContext | null): ExpressionFeatures {
  const b = obs.blendshapes;
  const bs = b ? channels(b) : null;
  const bsDelta = b && rest?.blendshapes ? channels(b, rest.blendshapes) : null;
  if (!rest || obs.landmarks.length < 468 * 3) return { bs, bsDelta, geo: null, magnitude: null };
  const geo = {} as Record<MovementTaskId, number>;
  for (const t of MOVEMENT_TASKS) {
    const v = measureLive(t, rest.ref, obs, RELAXED_QUALITY);
    geo[t] = v ? Math.min(3, Math.max(0, v.excursion.left, v.excursion.right) / FULL_EXCURSION[t]) : 0;
  }
  return { bs, bsDelta, geo, magnitude: expressionMagnitude(rest.ref, obs, RELAXED_QUALITY) };
}

/** Model input for the reference-free model ('single') or the model with a rest photo ('paired'). */
export function featureVector(f: ExpressionFeatures): { kind: 'paired' | 'single'; x: number[] } | null {
  if (f.bsDelta && f.geo) return { kind: 'paired', x: [...CHANNELS.map((c) => f.bsDelta![c]), ...MOVEMENT_TASKS.map((t) => f.geo![t]), 1] };
  if (f.bs) return { kind: 'single', x: [...CHANNELS.map((c) => f.bs![c]), 1] };
  return null;
}

export const FEATURE_NAMES = {
  paired: [...CHANNELS.map((c) => `d_${c}`), ...MOVEMENT_TASKS.map((t) => `geo_${t}`), 'bias'],
  single: [...CHANNELS.map((c) => `bs_${c}`), 'bias'],
} as const;

export interface ExpressionGuess {
  label: ExpressionLabel;
  /** Winner's probability minus the runner-up's (0–1): how clear the call was. */
  confidence: number;
  /** Model probabilities per label ('other' carries the rule's verdict as 0/1). */
  probs: Record<ExpressionLabel, number>;
  /**
   * Movement strength per task on the "fraction of a typical full movement" scale (geometric when a rest photo is
   * given, else blendshape): picks the held frames of a video segment. rest = 1 − strongest.
   */
  strength: Record<ExpressionLabel, number>;
  /** paired: blendshapes + rest photo; single: blendshapes only; geo: landmarks only (stored data), strongest task. */
  model: 'paired' | 'single' | 'geo' | null;
}

function softmax(z: number[]): number[] {
  const m = Math.max(...z);
  const e = z.map((v) => Math.exp(v - m));
  const s = e.reduce((a, b) => a + b, 0);
  return e.map((v) => v / s);
}

const BLEND_OF: Record<MovementTaskId, BlendChannel> = {
  brow: 'brow',
  eyeClose: 'eye',
  smile: 'smile',
  snarl: 'upperLip',
  pucker: 'pucker',
};

export function classifyExpression(f: ExpressionFeatures): ExpressionGuess {
  const strength = {} as Record<ExpressionLabel, number>;
  for (const t of MOVEMENT_TASKS) strength[t] = f.geo ? f.geo[t] : f.bs ? f.bs[BLEND_OF[t]] : 0;
  strength.rest = Math.max(0, 1 - Math.max(...MOVEMENT_TASKS.map((t) => strength[t])));
  strength.other = f.bsDelta ? Math.max(0, f.bsDelta.jaw) : f.bs ? f.bs.jaw : 0;
  const probs = Object.fromEntries(EXPRESSION_LABELS.map((l) => [l, 0])) as Record<ExpressionLabel, number>;
  const v = featureVector(f);
  if (!v && f.geo) {
    // Landmarks without blendshapes (e.g. stored coordinates): the strongest task movement, or rest.
    const ranked = MOVEMENT_TASKS.map((t) => [t, strength[t]] as const).sort((a, b) => b[1] - a[1]);
    const top = ranked[0]!;
    const label: ExpressionLabel = top[1] >= GEO_REST_BELOW ? top[0] : 'rest';
    probs[label] = 1;
    return { label, confidence: Math.min(1, top[1] - ranked[1]![1]), probs, strength, model: 'geo' };
  }
  if (!v) return { label: 'other', confidence: 0, probs, strength, model: null };
  const W = EXPRESSION_MODEL[v.kind];
  const p = softmax(W.map((row) => row.reduce((s, w, i) => s + w * v.x[i]!, 0)));
  MODEL_LABELS.forEach((l, i) => (probs[l] = p[i]!));
  const ranked = MODEL_LABELS.map((l) => [l, probs[l]] as const).sort((a, b) => b[1] - a[1]);
  let label: ExpressionLabel = ranked[0]![0];
  // Mouth open without a task movement: talking or yawning, not a usable rest photo.
  const jawOpen = f.bsDelta ? f.bsDelta.jaw > OTHER_JAW.delta : f.bs ? f.bs.jaw > OTHER_JAW.raw : false;
  if (label === 'rest' && jawOpen) {
    label = 'other';
    probs.other = 1;
  }
  return { label, confidence: ranked[0]![1] - ranked[1]![1], probs, strength, model: v.kind };
}

/**
 * The rest photo of a batch of photos of one person (upload assessment). With three or more: among the photos the
 * others differ from least (every movement moves away from rest in its own direction, so rest sits in the middle;
 * within 1.3× of the smallest sum), the one the reference-free model finds calmest. Yale 15 × 5 shuffled photos:
 * rest right in 15/15 (the sum alone 13/15 — a one-eye wink sits near rest too). Two photos: the calmer one.
 * Returns an index into `obs`, or -1 (fewer than two faces).
 */
export function pickRestIndex(obs: readonly FrameObservation[]): number {
  const faces = obs.map((o, i) => [o, i] as const).filter(([o]) => o.landmarks.length >= 468 * 3);
  if (faces.length < 2) return -1;
  const calm = (o: FrameObservation) => classifyExpression(expressionFeatures(o, null)).probs.rest;
  if (faces.length === 2) return calm(faces[0]![0]) >= calm(faces[1]![0]) ? faces[0]![1] : faces[1]![1];
  const ranked: { i: number; o: FrameObservation; sum: number }[] = [];
  for (const [c, i] of faces) {
    const ctx = restContext(c);
    if (!ctx) continue;
    let sum = 0;
    for (const [o] of faces) if (o !== c) sum += expressionFeatures(o, ctx).magnitude ?? 1;
    ranked.push({ i, o: c, sum });
  }
  if (!ranked.length) return -1;
  ranked.sort((a, b) => a.sum - b.sum);
  const close = ranked.filter((r) => r.sum <= 1.3 * ranked[0]!.sum);
  return close.reduce((best, r) => (calm(r.o) > calm(best.o) ? r : best)).i;
}
