/**
 * Weekly patient check (SRS-PRO-002): home-exercise adherence, the reasons it fell short, confidence in doing the
 * movements right, and four everyday burdens. Clinicians said patients skip their home exercises because they forget
 * or fear doing them wrong; this asks exactly that. Off by default (Settings › 환자 설문).
 *
 * These are the app's own items, NOT a validated scale. The validated Korean SAQ and FDI need their authors'
 * permission first (docs/11-prom-options.md). Their slots are listed but cannot be switched on.
 */
export const CHECKIN_VERSION = 'CHK-0.1.0';
export const CHECKIN_EVERY_DAYS = 7;
export const CHECKIN_CAP = 200;

export interface Choice {
  value: string;
  label: string;
}

export interface Question {
  id: string;
  text: string;
  kind: 'single' | 'multi' | 'scale';
  options?: Choice[];
  /** Scale ends (0–10). */
  minLabel?: string;
  maxLabel?: string;
  /** Asked only when this holds for the answers so far. */
  showIf?: (a: CheckinAnswers) => boolean;
}

export type CheckinAnswers = Record<string, string | string[] | number>;

export interface CheckinRecord {
  id: string;
  /** ISO time and local date of the answer. */
  at: string;
  date: string;
  version: string;
  answers: CheckinAnswers;
}

