/** Validated scales that can be added once their authors allow it (docs/11-prom-options.md). */
export const LICENSED_SCALES = [
  { id: 'SAQ', label: 'SAQ 연합운동 설문 (9문항, 한국어판 Nam 등 2023)' },
  { id: 'FDI', label: 'FDI 안면장애지수 (10문항, 한국어판 Nam 등 2026)' },
] as const;

/** Questions to show for the answers given so far. */
export const visibleQuestions = (a: CheckinAnswers): Question[] => CHECKIN.filter((q) => !q.showIf || q.showIf(a));

/** Complete when every visible question is answered (a multi-choice may stay empty). */
export const isComplete = (a: CheckinAnswers): boolean => visibleQuestions(a).every((q) => q.kind === 'multi' || a[q.id] !== undefined);

/** Keeps only the answers to visible questions (a changed first answer can hide the second). */
export const cleanAnswers = (a: CheckinAnswers): CheckinAnswers =>
  Object.fromEntries(visibleQuestions(a).flatMap((q) => (a[q.id] === undefined ? [] : [[q.id, a[q.id]!]])));

const daysBetween = (a: string, b: string) => Math.round((Date.parse(`${b}T00:00:00`) - Date.parse(`${a}T00:00:00`)) / 86400000);

/** Due when never answered, or the last answer is CHECKIN_EVERY_DAYS or more old. */
export function checkinDue(records: readonly CheckinRecord[], today: string): boolean {
  const last = records[records.length - 1];
  return !last || daysBetween(last.date, today) >= CHECKIN_EVERY_DAYS;
}

const label = (cs: Choice[] | undefined, v: unknown) => cs?.find((c) => c.value === v)?.label ?? String(v);

export interface CheckinAdvice {
  tone: 'warn' | 'info';
  text: string;
  /** Where the answer can be acted on in the app. */
  href?: string;
  cta?: string;
}

/** Eye or pain answers at or above this (0–10) bring the see-your-doctor advice. */
export const CHECKIN_ALERT = 7;

/**
 * What the app says back after a check (SRS-PRO-002): the reasons clinicians hear (forgot, unsure) point to the
 * reminders and the live guide; eye discomfort and pain point to the doctor. Never a diagnosis.
 */
export function checkinAdvice(a: CheckinAnswers): CheckinAdvice[] {
  const out: CheckinAdvice[] = [];
  const barriers = Array.isArray(a.barriers) ? a.barriers : [];
  if (typeof a.eye === 'number' && a.eye >= CHECKIN_ALERT) {
    out.push({
      tone: 'warn',
      text: '눈 불편이 큽니다. 인공눈물·안연고와 잘 때 눈 보호를 주치의와 상의하세요. 눈이 아프거나 빨개지거나 잘 안 보이면 바로 진료를 받으세요.',
    });
  }
  if (barriers.includes('pain')) {
    out.push({ tone: 'warn', text: '운동할 때 아프면 그 동작은 멈추고, 다음 진료 때 주치의나 치료사에게 알려 주세요.' });
  }
  if (barriers.includes('forgot')) {
    out.push({ tone: 'info', text: '운동 시간을 휴대폰 달력에 넣어 두면 잊지 않게 알려 줍니다.', href: '#/settings', cta: '알림 설정' });
  }
  if (barriers.includes('unsure') || a.confidence === 'unsure' || a.confidence === 'no') {
    out.push({
      tone: 'info',
      text: '운동 화면의 ‘내 얼굴로 따라하기’에서 실시간 안내를 시작하면 어디까지 움직이면 되는지, 잘 되고 있는지 화면에 보여 줍니다.',
      href: '#/rehab',
      cta: '운동하러 가기',
    });
  }
  return out;
}

/** One line for the clinician summary. */
export function checkinSummary(r: CheckinRecord): string {
  const a = r.answers;
  const parts = [`운동 ${label(ADHERENCE, a.adherence)}`];
  const barriers = Array.isArray(a.barriers) ? a.barriers : [];
  if (barriers.length) parts.push(`못 한 이유: ${barriers.map((b) => label(BARRIERS, b)).join(', ')}`);
  const conf = CHECKIN.find((q) => q.id === 'confidence')!.options;
  if (a.confidence !== undefined) parts.push(`동작 자신감: ${label(conf, a.confidence)}`);
  const scales = (['eye', 'eating', 'tightness', 'social'] as const).filter((k) => typeof a[k] === 'number');
  const names = { eye: '눈 불편', eating: '먹기 불편', tightness: '당김·같이 움직임', social: '대인 불편' };
  if (scales.length) parts.push(scales.map((k) => `${names[k]} ${a[k]}/10`).join(' · '));
  return parts.join(' · ');
}
