/** Settings › 알림: exercise times, the weekly re-assessment, calendar export and best-effort app notifications (SRS-RHB-017). */
import { useState } from 'preact/hooks';
import { download } from '../../data/export';
import { actions } from '../../data/store';
import type { Profile } from '../../data/types';
import {
  ASSESS_TITLE,
  DEFAULT_REMINDERS,
  EXERCISE_TITLE,
  MAX_EXERCISE_TIMES,
  WEEKDAY_LABEL,
  cleanTimes,
  googleCalendarLink,
  remindersIcs,
  timeLabel,
  type Reminders,
} from '../../rehab/reminders';
import { disableNotify, enableNotify, notifyStatus, type NotifyStatus } from '../notify';
import { Notice } from './common';

const STATUS_TEXT: Record<NotifyStatus, string> = {
  unsupported: '이 브라우저는 앱 알림을 지원하지 않습니다.',
  default: '켜면 알림 권한을 묻습니다.',
  granted: '알림 권한이 허용되어 있습니다.',
  denied: '알림 권한이 거부되어 있습니다. 브라우저 설정에서 이 사이트의 알림을 허용해 주세요.',
};

const appUrl = () => `${location.origin}${location.pathname}#/rehab`;
const ICS_DAY = ['SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'] as const;

export function ReminderSettings({ profile }: { profile: Profile }) {
  const r = profile.reminders;
  const [status, setStatus] = useState<NotifyStatus>(notifyStatus());
  const [note, setNote] = useState<string | null>(null);
  const save = (next: Reminders | undefined) => actions.saveProfile({ ...profile, reminders: next });

  if (!r) {
    return (
      <div class="card">
        <p class="small ink2" style={{ margin: 0 }}>
          운동을 잊지 않도록 정한 시간에 알려 드립니다. 휴대폰 달력에 넣으면 앱을 열지 않아도 울립니다.
        </p>
        <button class="btn primary block" onClick={() => save(DEFAULT_REMINDERS)}>
          알림 켜기 (운동 오전 9시·오후 8시, 평가 월요일 오전 10시)
        </button>
      </div>
    );
  }

  const times = cleanTimes(r.exercise);
  const setTimes = (next: string[]) => save({ ...r, exercise: cleanTimes(next) });
  const toggleNotify = async (on: boolean) => {
    if (!on) {
      await disableNotify();
      setNote(null);
      return save({ ...r, notify: false });
    }
    const res = await enableNotify();
    setStatus(res.status);
    setNote(
      res.status !== 'granted'
        ? null
        : res.periodic
          ? '설치한 앱에서 알림 시간이 지나도 운동 기록이 없으면 알려 드립니다. 휴대폰이 알림을 늦게 보낼 수 있어 달력 알림을 함께 쓰세요.'
          : '이 기기는 앱이 닫혀 있을 때 알림을 보낼 수 없습니다. 달력 알림을 쓰세요.',
    );
    return save({ ...r, notify: res.status === 'granted' });
  };

  return (
    <div class="card">
      <div class="field">
        <span>운동 알림 (매일)</span>
        <div class="stack">
          {times.map((t, k) => (
            <div class="row between">
              <input
                id={`reminder-time-${k}`}
                type="time"
                value={t}
                aria-label={`운동 알림 ${k + 1}`}
                onChange={(e) => setTimes(times.map((x, j) => (j === k ? (e.target as HTMLInputElement).value : x)))}
              />
              <button class="btn sm ghost" onClick={() => setTimes(times.filter((_, j) => j !== k))}>
                삭제
              </button>
            </div>
          ))}
          {times.length < MAX_EXERCISE_TIMES && (
            <button class="btn sm" onClick={() => setTimes([...times, times.includes('13:00') ? '17:00' : '13:00'])}>
              시간 추가
            </button>
          )}
        </div>
      </div>
      <div class="field">
        <span>평가 알림 (매주)</span>
        {r.assess ? (
          <div class="row between">
            <select
              id="reminder-assess-day"
              aria-label="평가 요일"
              value={String(r.assess.day)}
              onChange={(e) => save({ ...r, assess: { ...r.assess!, day: Number((e.target as HTMLSelectElement).value) } })}
            >
              {WEEKDAY_LABEL.map((d, i) => (
                <option value={String(i)}>{d}요일</option>
              ))}
            </select>
            <input
              id="reminder-assess-time"
              type="time"
              aria-label="평가 시간"
              value={r.assess.time}
              onChange={(e) => save({ ...r, assess: { ...r.assess!, time: (e.target as HTMLInputElement).value } })}
            />
            <button class="btn sm ghost" onClick={() => save({ ...r, assess: null })}>
              끄기
            </button>
          </div>
        ) : (
          <button class="btn sm" onClick={() => save({ ...r, assess: DEFAULT_REMINDERS.assess })}>
            평가 알림 켜기
          </button>
        )}
      </div>

      <div class="stack">
        <button class="btn primary block" onClick={() => download('얼굴운동_알림.ics', remindersIcs(r, appUrl()), 'text/calendar')}>
          휴대폰 달력에 넣기 (.ics · 삼성 캘린더·아이폰)
        </button>
        {times.map((t) => (
          <a
            class="btn ghost block"
            href={googleCalendarLink(EXERCISE_TITLE, t, 'FREQ=DAILY', `오늘의 얼굴 운동을 해 주세요. ${appUrl()}`)}
            target="_blank"
            rel="noopener"
          >
            구글 캘린더에 {timeLabel(t)} 운동 추가
          </a>
        ))}
        {r.assess && (
          <a
            class="btn ghost block"
            href={googleCalendarLink(
              ASSESS_TITLE,
              r.assess.time,
              `FREQ=WEEKLY;BYDAY=${ICS_DAY[r.assess.day]}`,
              `일주일에 한 번 얼굴 평가를 해 주세요. ${appUrl()}`,
              new Date(),
              5,
            )}
            target="_blank"
            rel="noopener"
          >
            구글 캘린더에 {WEEKDAY_LABEL[r.assess.day]}요일 평가 추가
          </a>
        )}
        <p class="xsmall muted" style={{ margin: 0 }}>
          달력 알림은 앱을 열지 않아도 울립니다. 시간을 바꾸면 달력에 다시 넣어 주세요. 제목은 ‘{EXERCISE_TITLE}’으로, 병명은 적지 않습니다.
        </p>
      </div>

      <label class="check" style={{ padding: 0 }}>
        <input
          id="reminder-notify"
          type="checkbox"
          checked={r.notify}
          disabled={status === 'unsupported'}
          onChange={(e) => void toggleNotify((e.target as HTMLInputElement).checked)}
        />
        <span>
          앱 알림 (시험) <span class="small muted">— 안드로이드에 설치한 앱에서, 알림 시간이 지나도 운동을 안 했으면 알려 줍니다</span>
        </span>
      </label>
      <p class="xsmall muted" style={{ margin: 0 }}>
        {STATUS_TEXT[status]}
      </p>
      {note && (
        <Notice tone="info">
          <span class="small">{note}</span>
        </Notice>
      )}
      <button class="btn sm ghost" onClick={() => void disableNotify().then(() => save(undefined))}>
        알림 모두 끄기
      </button>
    </div>
  );
}
