/**
 * Rule-based personalisation of the daily rehabilitation plan.
 * Pure and deterministic: (profile facts, latest assessment) → plan with a
 * human-readable reason for every item (explainability requirement SRS-RHB-002).
 *
 * Order (RP-0.2.0, SRS-RHB-021): what matters most comes first, and the routine plays in this order.
 *  1. eye protection while the eye does not close;
 *  2. the regions weakest first, each one's preparation (massage) right before its exercises;
 *  3. items tied to no single region;
 *  4. relaxation (breathing) to finish. In the synkinesis programme relaxing is the core and comes first, and the
 *     stronger measured synkinesis pattern goes before the other.
 * Without an assessment no item is called the weakest: the regions take a default order (eye protection, then eating
 * and speech, then the forehead).
 */
import type { AnalysisResult, MovementTaskId } from '../core';
import { EXERCISES, REGION_LABEL, type Exercise, type Phase } from './exercises';
import { regionFinding, type FaceRegion } from './findings';

export const PLANNER_VERSION = 'RP-0.2.0';

export interface PlanInput {
  daysSinceOnset: number;
  /** Most recent complete assessment, if any. */
  latest: AnalysisResult | null;
}

/** What an item is for in today's order (SRS-RHB-021). */
export type PlanRole = 'safety' | 'prep' | 'core' | 'relax';

export interface PlanItem {
  exercise: Exercise;
  reason: string;
  /** Region whose measured weakness put this item on the plan. */
  region?: FaceRegion;
  role: PlanRole;
  /** 1 = the weakest measured region (or the stronger synkinesis pattern); unset with no measurement behind it. */
  rank?: number;
}

export interface Plan {
  version: string;
  phase: Phase;
  phaseReason: string;
  sessionsPerDay: number;
  items: PlanItem[];
  notices: string[];
  /** The measured regions weakest first, as the plan ordered them (empty without an assessment). */
  priorities: { region: FaceRegion; pct: number }[];
}

/** Days after onset at which the plan switches from acute to recovery. */
export const ACUTE_DAYS = 21;
/** Total synkinesis score at or above which the synkinesis programme is used. */
export const SYNKINESIS_THRESHOLD = 3;
/** Region order without an assessment: eye protection, then eating and speech, then the forehead. */
export const DEFAULT_REGION_ORDER: readonly FaceRegion[] = ['eye', 'mouth', 'forehead', 'midface'];

function phaseOf(input: PlanInput): { phase: Phase; reason: string } {
  const synk = input.latest?.scores?.synkinesisScore ?? 0;
  if (synk >= SYNKINESIS_THRESHOLD) {
    return { phase: 'synkinesis', reason: `최근 평가에서 동반운동 점수가 ${synk}점으로 확인되어 동반운동 관리 단계를 적용합니다.` };
  }
  if (input.daysSinceOnset < ACUTE_DAYS) {
    return {
      phase: 'acute',
      reason: `발병 ${input.daysSinceOnset + 1}일째로 급성기(3주 이내)입니다. 부드러운 마사지와 눈 보호 위주로 진행합니다.`,
    };
  }
  return { phase: 'recovery', reason: `발병 ${input.daysSinceOnset + 1}일째 회복기입니다. 거울을 보며 작고 대칭적인 움직임을 연습합니다.` };
}

const MASSAGE_FOR: Record<FaceRegion, string> = {
  forehead: 'massage-forehead',
  eye: 'massage-eye',
  midface: 'massage-cheek',
  mouth: 'massage-lips',
};
/** Selective stretches of the reference video per region (most specific first). */
const STRETCH_FOR: Record<FaceRegion, string[]> = {
  forehead: ['frontalis-lift', 'brow-relax'],
  eye: ['eye-open', 'orbicularis-sweep'],
  midface: ['levator-labii', 'levator-superioris'],
  mouth: ['zygomatic-lift', 'corner-lift'],
};
const NMR_FOR: Record<FaceRegion, string[]> = {
  forehead: ['nmr-brow'],
  eye: ['nmr-eye'],
  midface: ['nmr-snarl'],
  mouth: ['nmr-smile', 'nmr-pucker'],
};

export function buildPlan(input: PlanInput): Plan {
  const { phase, reason: phaseReason } = phaseOf(input);
  const s = input.latest?.scores ?? null;
  const items: PlanItem[] = [];
  const notices: string[] = [];
  const add = (id: string, reason: string, role: PlanRole, region?: FaceRegion, rank?: number) => {
    const ex = EXERCISES.find((e) => e.id === id);
    if (ex && ex.phases.includes(phase) && !items.some((i) => i.exercise.id === id))
      items.push({ exercise: ex, reason, role, region, rank });
  };

  // 1. Eye protection.
  const eyeIncomplete = s ? !s.eyeClosureComplete : phase === 'acute';
  if (eyeIncomplete) {
    add(
      'eyecare',
      s ? '최근 평가에서 눈이 완전히 감기지 않아 눈 보호를 가장 먼저 챙깁니다.' : '급성기에는 눈 보호가 가장 중요합니다.',
      'safety',
    );
    notices.push('눈이 완전히 감기지 않습니다. 인공눈물·안연고 사용과 수면 중 눈 보호에 대해 주치의와 상의하세요.');
  }

  // Regions weakest first (deficit = 100 − % of the healthy side); ties and the unassessed keep the default order.
  // An eye that does not close goes first whatever its percentage: protecting the cornea comes before the rest.
  const ranked = DEFAULT_REGION_ORDER.map((region) => ({ region, deficit: s ? 100 - s.regional[region] : 50 })).sort(
    (a, b) => (eyeIncomplete && s ? Number(b.region === 'eye') - Number(a.region === 'eye') : 0) || b.deficit - a.deficit,
  );
  const evidence = (r: FaceRegion) => (s ? `${REGION_LABEL[r]}: ${regionFinding(input.latest!, r)!.evidence}` : REGION_LABEL[r]);

  if (phase === 'acute') {
    // 2. Every region gets a gentle massage, the weakest first; gentle eye closure follows the eye massage.
    ranked.forEach(({ region: r }, k) => {
      const reg = s ? r : undefined;
      const rank = s ? k + 1 : undefined;
      add(MASSAGE_FOR[r], `${evidence(r)}${s ? '' : ' 기본 관리'} — 급성기에는 부드러운 마사지로 관리합니다.`, 'core', reg, rank);
      if (r === 'eye')
        add(
          'nmr-eye',
          `${s ? `${evidence(r)} — ` : ''}눈 감기는 급성기에도 가볍게 시도할 수 있는 동작입니다. 눈 마사지에 이어서 합니다.`,
          'core',
          reg,
          rank,
        );
    });
    notices.push('급성기에는 최대 힘으로 얼굴을 움직이는 운동과 전기자극을 피하세요. 치료 방법은 주치의와 상의하세요.');
  } else if (phase === 'recovery') {
    // 2. Up to three regions below 90 %, weakest first: preparation massage (first two) → re-training → (weakest) stretch.
    const needs = s ? ranked.filter((x) => x.deficit >= 10) : ranked;
    needs.slice(0, 3).forEach(({ region: r, deficit: d }, k) => {
      const reg = s ? r : undefined;
      const rank = s ? k + 1 : undefined;
      if (k < 2) add(MASSAGE_FOR[r], `${evidence(r)} — 이 부위 운동 전에 근육을 풀어 줍니다.`, 'prep', reg, rank);
      const why = !s
        ? '기본 운동입니다. 평가하면 약한 부위부터 바뀝니다'
        : r === 'eye' && eyeIncomplete && k === 0
          ? '눈이 다 감기지 않아 먼저 합니다'
          : k === 0
            ? '가장 약해 먼저 합니다'
            : `${k + 1}번째로 약한 부위입니다`;
      for (const id of NMR_FOR[r]) add(id, `${evidence(r)} — ${why}.`, 'core', reg, rank);
      if (r === 'mouth' && d >= 20)
        add(
          'nmr-cheek-puff',
          s ? `${evidence(r)} — 입술 닫는 힘도 함께 연습합니다.` : '입술 닫는 힘을 함께 연습하는 기본 운동입니다.',
          'core',
          reg,
          rank,
        );
      // Selective stretching is recommended from the early phase onward (reference video), for the measured weakest.
      if (k === 0 && s) add(STRETCH_FOR[r][0]!, `${evidence(r)} — 가장 약한 부위의 선택적 스트레칭입니다.`, 'core', reg, rank);
    });
    if (s && needs.length === 0) add('nmr-smile', '모든 부위가 90% 이상 회복되어 유지 운동만 권장합니다.', 'core');
  } else {
    // Relaxing is the core of synkinesis management: first. Then the stronger measured pattern before the other.
    add('relax-breath', '동반운동 관리는 얼굴 힘을 빼는 것부터 시작합니다.', 'relax');
    const grade = (t: MovementTaskId) => input.latest?.tasks[t]?.synkinesisGrade ?? 0;
    // Eye narrowing while the mouth moves; the mouth pulling while the eye or brow moves.
    const eyeSynk = s ? grade('smile') + grade('snarl') + grade('pucker') : 1;
    const mouthSynk = s ? grade('brow') + grade('eyeClose') : 1;
    const eyeBlock = (rank: number) => {
      const r = eyeSynk > 0 ? rank : undefined;
      add('massage-eye', '동반운동으로 긴장된 눈 주위 근육을 먼저 풀어 줍니다.', 'prep', eyeSynk > 0 ? 'eye' : undefined, r);
      if (eyeSynk > 0) {
        add('eye-open', '눈이 함께 작아지는 동반운동이 있어 짧아진 눈둘레근을 안쪽→바깥쪽으로 늘입니다.', 'core', 'eye', r);
        add('orbicularis-sweep', '이어서 눈둘레근을 위·아래로 늘입니다.', 'core', 'eye', r);
        add('dissoc-smile-eye', '입을 움직일 때 눈이 함께 작아지는 동반운동이 측정되었습니다.', 'core', 'eye', r);
      }
    };
    const mouthBlock = (rank: number) => {
      const r = mouthSynk > 0 ? rank : undefined;
      const reg = mouthSynk > 0 ? ('mouth' as const) : undefined;
      add('massage-cheek', '처진 볼과 입꼬리 주위를 부드럽게 풀어 줍니다.', 'prep', reg, r);
      add('zygomatic-lift', '광대근을 늘여 입꼬리가 과하게 당기는 긴장을 풀어 줍니다.', 'core', reg, r);
      add('corner-lift', '입꼬리올림근을 늘여 웃을 때 과하게 당기는 긴장을 풀어 줍니다.', 'core', reg, r);
      if (mouthSynk > 0) add('dissoc-eye-mouth', '눈을 감을 때 입꼬리가 따라 움직이는 동반운동이 측정되었습니다.', 'core', 'mouth', r);
    };
    if (mouthSynk > eyeSynk) {
      mouthBlock(1);
      eyeBlock(2);
    } else {
      eyeBlock(1);
      mouthBlock(2);
    }
    // 3. No single region.
    add('platysma-lift', '입 움직임과 함께 목이 당기는 긴장을 완화합니다.', 'core');
    notices.push('동반운동이 있을 때는 근력 강화보다 이완·스트레칭·분리 운동이 우선입니다. 보툴리눔 주사 등 치료는 주치의와 상의하세요.');
  }

  // 4. Relaxation to finish (acute and recovery).
  add('relax-breath', '마무리로 숨을 고르며 얼굴 힘을 뺍니다.', 'relax');

  if (input.daysSinceOnset >= 21 && s && s.functionIndex < 30) {
    notices.push('발병 3주 이후에도 움직임이 매우 적습니다. 아직 진료를 받지 않았다면 이비인후과·신경과·재활의학과 진료를 권합니다.');
  }

  const priorities = s && phase !== 'synkinesis' ? ranked.map(({ region }) => ({ region, pct: s.regional[region] })) : [];
  return { version: PLANNER_VERSION, phase, phaseReason, sessionsPerDay: phase === 'acute' ? 2 : 3, items, notices, priorities };
}

/** Short tag for an item's place in today's order (SRS-RHB-021): '1순위 · 입', '준비', '먼저', '마무리'. */
export function planTag(item: PlanItem, phase: Phase): string {
  if (item.role === 'safety') return '가장 먼저';
  if (item.role === 'relax') return phase === 'synkinesis' ? '시작' : '마무리';
  const where = item.region ? ` · ${REGION_LABEL[item.region]}` : '';
  if (item.role === 'prep') return `준비${where}`;
  return item.rank ? `${item.rank}순위${where}` : '기본';
}

export const PHASE_LABEL: Record<Phase, string> = {
  acute: '급성기',
  recovery: '회복기',
  synkinesis: '동반운동 관리기',
};
