/**
 * An algorithm version (or the GPU/CPU that ran the face model) shown as text that opens what it means when tapped:
 * what the algorithm does, what this record's version changed, the version history (ui/algorithms.ts). SRS-USA-009.
 */
import { render } from 'preact';
import { useEffect, useRef, useState } from 'preact/hooks';
import { ALGO_NOTES, versionNote, type AlgoId } from '../algorithms';

interface Props {
  id: AlgoId;
  /** This record's version (absent: the explanation only). */
  version?: string;
  /** ENGINE: which processor ran the face model for this record. */
  delegate?: 'GPU' | 'CPU';
  /** Shown text; default `FPA-GEOM 0.6.0`, `SC-0.2.0`, or the processor. */
  label?: string;
}

export function AlgoTag({ id, version, delegate, label }: Props) {
  const [open, setOpen] = useState(false);
  const button = useRef<HTMLButtonElement>(null);
  // The sheet lives in its own node under <body>, so a card, table or paragraph around the tag cannot clip it.
  useEffect(() => {
    if (!open) return undefined;
    const host = document.createElement('div');
    document.body.appendChild(host);
    const close = () => setOpen(false);
    render(<AlgoSheet id={id} version={version} delegate={delegate} onClose={close} />, host);
    return () => {
      render(null, host);
      host.remove();
      button.current?.focus();
    };
  }, [open]);
  const text = label ?? (id === 'ENGINE' ? (delegate ?? 'GPU/CPU') : version ? (id === 'SC' ? version : `${id} ${version}`) : id);
  return (
    <button type="button" ref={button} class="algo-tag" aria-haspopup="dialog" onClick={() => setOpen(true)}>
      {text}
    </button>
  );
}

function AlgoSheet({ id, version, delegate, onClose }: Props & { onClose: () => void }) {
  const n = ALGO_NOTES[id];
  const now = version ? versionNote(id, version) : undefined;
  const closeBtn = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    closeBtn.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);
  return (
    <div class="sheet-backdrop" onClick={onClose}>
      <div class="sheet" role="dialog" aria-modal="true" aria-labelledby="algo-sheet-title" onClick={(e) => e.stopPropagation()}>
        <div class="row" style={{ justifyContent: 'space-between', alignItems: 'center', gap: '8px' }}>
          <h3 id="algo-sheet-title" style={{ margin: 0 }}>
            {n.title}
          </h3>
          <button type="button" ref={closeBtn} class="btn sm ghost" onClick={onClose}>
            닫기
          </button>
        </div>
        <p class="small">{n.what}</p>
        {id === 'ENGINE' && delegate && (
          <p class="small">
            <b>이 기록은 {delegate === 'GPU' ? 'GPU(그래픽 칩)' : 'CPU'}로 계산했습니다.</b>
          </p>
        )}
        {now && (
          <div class="sheet-now">
            <b>이 기록: {now.v}</b> <span class="xsmall muted">({now.date})</span>
            <div class="small">{now.text}</div>
          </div>
        )}
        {n.versions.length > 0 && (
          <details open={!now}>
            <summary class="small ink2">버전별로 바뀐 점</summary>
            <ul class="xsmall" style={{ margin: '6px 0 0', paddingLeft: '18px' }}>
              {n.versions.map((x) => (
                <li class={x.v === version ? 'now' : undefined}>
                  <b>{x.v}</b> <span class="muted">({x.date})</span> {x.text}
                </li>
              ))}
            </ul>
          </details>
        )}
        {n.note && <p class="xsmall muted">{n.note}</p>}
      </div>
    </div>
  );
}
