/**
 * Best-effort reminder notifications for the installed app (SRS-RHB-017). Without a server there is no push: Android
 * Chrome's periodic background sync wakes the service worker now and then, and the service worker notifies when a
 * reminder time has passed and nothing was logged today. The browser decides when that happens, so the calendar
 * reminders stay the reliable route. The state the service worker reads lives in its own cache entry.
 */
import type { Reminders } from '../rehab/reminders';
import { cleanTimes } from '../rehab/reminders';

export const REMINDER_CACHE = 'fpc-reminders';
export const REMINDER_KEY = './__fpc-reminders';
const SYNC_TAG = 'fpc-remind';

export type NotifyStatus = 'unsupported' | 'default' | 'granted' | 'denied';

export function notifyStatus(): NotifyStatus {
  if (typeof Notification === 'undefined' || !('serviceWorker' in navigator)) return 'unsupported';
  return Notification.permission as NotifyStatus;
}

interface PeriodicSyncRegistration extends ServiceWorkerRegistration {
  periodicSync?: { register: (tag: string, o: { minInterval: number }) => Promise<void>; unregister: (tag: string) => Promise<void> };
}

/** Asks for permission and registers the periodic wake-up; returns the permission and whether the wake-up is on. */
export async function enableNotify(): Promise<{ status: NotifyStatus; periodic: boolean }> {
  if (notifyStatus() === 'unsupported') return { status: 'unsupported', periodic: false };
  const status = (await Notification.requestPermission()) as NotifyStatus;
  if (status !== 'granted') return { status, periodic: false };
  try {
    const reg = (await navigator.serviceWorker.ready) as PeriodicSyncRegistration;
    if (!reg.periodicSync) return { status, periodic: false };
    await reg.periodicSync.register(SYNC_TAG, { minInterval: 3 * 60 * 60 * 1000 });
    return { status, periodic: true };
  } catch {
    return { status, periodic: false };
  }
}

export async function disableNotify(): Promise<void> {
  try {
    const reg = (await navigator.serviceWorker.ready) as PeriodicSyncRegistration;
    await reg.periodicSync?.unregister(SYNC_TAG);
  } catch {
    /* nothing registered */
  }
}

/** Writes what the service worker needs: the times, whether notifying is on, and the last day exercise was logged. */
export async function syncReminderState(r: Reminders | undefined, lastDone: string | null): Promise<void> {
  if (typeof caches === 'undefined') return;
  try {
    const c = await caches.open(REMINDER_CACHE);
    const res = await c.match(REMINDER_KEY);
    const prev: { lastNotified?: string | null } = res ? await res.json() : {};
    const body = { times: r?.notify ? cleanTimes(r.exercise) : [], lastDone, lastNotified: prev.lastNotified ?? null };
    await c.put(REMINDER_KEY, new Response(JSON.stringify(body), { headers: { 'content-type': 'application/json' } }));
  } catch {
    /* storage blocked */
  }
}
