/**
 * Research participation, item by item (SRS-DAT-013): the checkboxes (first run and settings) and the settings card
 * with the decision in force, changing it and withdrawing. Every change is recorded as a new decision.
 */
import { useState } from 'preact/hooks';
import {
  NO_RESEARCH_ITEMS,
  RESEARCH_CONSENT_POINTS,
  RESEARCH_ITEMS,
  RESEARCH_ITEM_SHORT,
  canGiveResearchData,
  researchConsentOf,
  researchDecision,
  type ResearchItem,
} from '../../data/consent';
import { actions } from '../../data/store';
import type { Profile } from '../../data/types';
import { fmtDate } from '../labels';
import { roleOf } from '../role';
import { Notice } from './common';

export type ResearchItems = Record<ResearchItem, boolean>;

export const NO_ITEMS: ResearchItems = { ...NO_RESEARCH_ITEMS };

/** The optional items follow participation: off and disabled without it. */
export function ResearchItemsFields({ value, onChange }: { value: ResearchItems; onChange: (v: ResearchItems) => void }) {
  return (
    <>
      {RESEARCH_ITEMS.map((it) => (
        <label class="check">
          <input
            type="checkbox"
            checked={value[it.id]}
            disabled={it.id !== 'core' && !value.core}
            onChange={(e) => {
              const on = (e.target as HTMLInputElement).checked;
              onChange(it.id === 'core' && !on ? { ...NO_ITEMS } : { ...value, [it.id]: on });
            }}
          />
          <span class="small">
            {it.label}
            <span class="xsmall muted" style={{ display: 'block' }}>
              {it.detail}
            </span>
          </span>
        </label>
      ))}
      <details>
        <summary class="xsmall ink2">자료를 어떻게 건네고 보관하나요</summary>
        <ul class="xsmall ink2" style={{ margin: '4px 0 0', paddingLeft: '18px' }}>
          {RESEARCH_CONSENT_POINTS.map((t) => (
            <li>{t}</li>
          ))}
        </ul>
      </details>
    </>
  );
}

/** Saves a decision; photo consent also turns photo saving on (there is nothing to give otherwise). */
export async function saveResearchDecision(profile: Profile, items: ResearchItems, withdrawn = false): Promise<void> {
  const d = researchDecision(items, roleOf(profile), { withdrawn });
  await actions.saveProfile({
    ...profile,
    research: [...(profile.research ?? []), d],
    consent: { ...profile.consent, researchExport: canGiveResearchData(d) },
    ...(d.items.photos ? { savePhotos: true } : {}),
  });
}

const itemLine = (items: ResearchItems) =>
  RESEARCH_ITEMS.filter((it) => it.id !== 'core')
    .map((it) => `${RESEARCH_ITEM_SHORT[it.id]} ${items[it.id] ? '동의' : '안 함'}`)
    .join(' · ');

export function ResearchConsentCard({ profile }: { profile: Profile }) {
  const now = researchConsentOf(profile);
  const [edit, setEdit] = useState<ResearchItems | null>(null);
  const [busy, setBusy] = useState(false);
  const save = async (items: ResearchItems, withdrawn = false) => {
    setBusy(true);
    await saveResearchDecision(profile, items, withdrawn);
    setBusy(false);
    setEdit(null);
  };
  return (
    <div class="card">
      {now?.withdrawn ? (
        <Notice tone="warn">
          <span class="small">
            <b>연구 참여를 철회했습니다</b> ({fmtDate(now.at)}). 연구 자료 파일을 만들 수 없습니다. 이미 넘긴 자료는 연구진이 지웁니다 —
            연구 담당자에게 알려 주세요.
          </span>
        </Notice>
      ) : now?.items.core ? (
        <Notice tone="good">
          <span class="small">
            <b>연구 참여 중</b> · 측정값·얼굴 점 좌표 제공 · {itemLine(now.items)}
            <span class="xsmall muted" style={{ display: 'block' }}>
              동의 {now.version} · {fmtDate(now.at)}
            </span>
          </span>
        </Notice>
      ) : (
        <p class="small ink2" style={{ margin: 0 }}>
          연구에 참여하지 않습니다. 연구에 참여하게 되면 동의서에 적은 대로 여기에서 항목을 고르세요.
        </p>
      )}
      {edit ? (
        <>
          <ResearchItemsFields value={edit} onChange={setEdit} />
          <div class="row" style={{ marginTop: '8px' }}>
            <button class="btn grow" onClick={() => setEdit(null)}>
              취소
            </button>
            <button class="btn primary grow" disabled={busy} onClick={() => save(edit)}>
              이대로 저장
            </button>
          </div>
        </>
      ) : (
        <div class="row" style={{ marginTop: '8px' }}>
          <button class="btn sm grow" onClick={() => setEdit(now && !now.withdrawn ? { ...NO_ITEMS, ...now.items } : { ...NO_ITEMS })}>
            {now?.items.core ? '동의 항목 바꾸기' : '연구 참여 동의 기록'}
          </button>
          {now?.items.core && (
            <button
              class="btn sm ghost grow"
              disabled={busy}
              onClick={() => {
                if (
                  confirm(
                    '연구 참여를 철회합니다. 이후 연구 자료 파일을 만들 수 없고, 이미 넘긴 자료는 연구진이 지웁니다. 이 기기의 기록은 그대로 남습니다(지우려면 ‘모든 데이터 삭제’). 계속할까요?',
                  )
                )
                  void save({ ...NO_ITEMS }, true);
              }}
            >
              참여 철회
            </button>
          )}
        </div>
      )}
    </div>
  );
}
