/**
 * Rejected assessment steps (SRS-QC-006, SRS-DAT-012): every automatic retake is logged with its reason, the numbers
 * that triggered it and the face points of a few frames, so the pilot can see why steps keep failing and tune the
 * criteria. On this device only (the key-value store of the open profile or study subject), the last REJECTION_CAP
 * kept; the JSON export carries them. No images.
 */
import type { FrameObservation, QualityIssue } from '../core';

export const REJECTION_CAP = 100;
/** Frames kept per rejected attempt. */
export const REJECTION_FRAMES = 3;
/** Automatic retakes per step: the first rejection is retaken (with the example shown), the next one moves on. */
export const AUTO_RETAKES = 1;
/** Countdown before a retake (s), after the spoken reason: the example plays through both (SRS-USA-013). */
export const RETAKE_COUNTDOWN = 3;

/** What a rejected step does next, given how many times it was already retaken (SRS-QC-006). */
export const afterRejection = (retakesSoFar: number): 'retake' | 'moveOn' => (retakesSoFar < AUTO_RETAKES ? 'retake' : 'moveOn');

export type RejectReason = 'fewFrames' | 'jawOpen';

export interface RejectionRecord {
  id: string;
  at: string;
  /** Assessment step (a task id or a muscle step). */
  step: string;
  /** 1 = the first try of the step. */
  attempt: number;
  reason: RejectReason;
  /** The step moved on after this rejection (no automatic retake left). */
  movedOn: boolean;
  validFrames: number;
  totalFrames: number;
  issues: Partial<Record<QualityIssue, number>>;
  /** Smile: median chin drop of the strongest frames (inter-pupil units) and the limit it was held to. */
  jawDrop?: number;
  jawLimit?: number;
  app: { version: string; algorithm: string };
  /** Image size, and face points (pixels, 0.1 px) of the rest reference and of up to REJECTION_FRAMES frames. */
  width: number;
  height: number;
  rest: number[] | null;
  frames: { t: number; xy: number[] }[];
}

const xyOf = (o: FrameObservation): number[] => {
  const n = Math.floor(o.landmarks.length / 3);
  const out: number[] = [];
  for (let i = 0; i < n; i++)
    out.push(Math.round(o.landmarks[3 * i]! * o.width * 10) / 10, Math.round(o.landmarks[3 * i + 1]! * o.height * 10) / 10);
  return out;
};

/** Up to `k` frames with a face, spread over the list (the order the caller chose: strongest first, or in time). */
export function pickFrames(frames: readonly FrameObservation[], k = REJECTION_FRAMES): FrameObservation[] {
  const withFace = frames.filter((o) => o.landmarks.length >= 468 * 3);
  if (withFace.length <= k) return withFace;
  const step = withFace.length / k;
  return Array.from({ length: k }, (_, i) => withFace[Math.floor(i * step)]!);
}

export function makeRejection(r: {
  step: string;
  attempt: number;
  reason: RejectReason;
  movedOn: boolean;
  validFrames: number;
  totalFrames: number;
  issues: Partial<Record<QualityIssue, number>>;
  jawDrop?: number | null;
  jawLimit?: number;
  app: { version: string; algorithm: string };
  rest: FrameObservation | null;
  frames: readonly FrameObservation[];
  at?: Date;
}): RejectionRecord {
  const kept = r.frames.slice(0, REJECTION_FRAMES);
  const size = r.rest ?? kept[0];
  return {
    id: `rej-${(r.at ?? new Date()).getTime().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
    at: (r.at ?? new Date()).toISOString(),
    step: r.step,
    attempt: r.attempt,
    reason: r.reason,
    movedOn: r.movedOn,
    validFrames: r.validFrames,
    totalFrames: r.totalFrames,
    issues: r.issues,
    ...(r.jawDrop != null ? { jawDrop: Math.round(r.jawDrop * 1000) / 1000, jawLimit: r.jawLimit } : {}),
    app: r.app,
    width: size?.width ?? 0,
    height: size?.height ?? 0,
    rest: r.rest && r.rest.landmarks.length ? xyOf(r.rest) : null,
    frames: kept.map((o) => ({ t: Math.round(o.t), xy: xyOf(o) })),
  };
}

/** The log after adding `added`: oldest dropped past REJECTION_CAP. */
export const withRejections = (log: readonly RejectionRecord[], added: readonly RejectionRecord[]): RejectionRecord[] =>
  [...log, ...added].slice(-REJECTION_CAP);
