/** Minimal code-split screen loader (keeps the first-load bundle small, SRS-PRF-001). */
import type { ComponentType, JSX } from 'preact';
import { useEffect, useState } from 'preact/hooks';

export function lazyScreen<P extends object>(load: () => Promise<ComponentType<P>>): (props: P) => JSX.Element {
  let cached: ComponentType<P> | null = null;
  return function Lazy(props: P) {
    const [C, setC] = useState<ComponentType<P> | null>(() => cached);
    useEffect(() => {
      if (!cached) load().then((c) => setC(() => (cached = c)));
    }, []);
    return C ? <C {...props} /> : <div class="splash">불러오는 중…</div>;
  };
}
