/**
 * Measurement methods the research build can switch between (Settings > 측정 방식), for side-by-side tests on a
 * phone. Every result records its method in `algorithm.version`, so a change of method is flagged like a new
 * algorithm version (rehab/findings.ts versionChange).
 *
 * - v060: FPA-GEOM 0.6.0, the default (finer tracking for the pucker task).
 * - v050: FPA-GEOM 0.5.0 (every task on the 140 px crop).
 * - raft: hybrid — eye closure as v060 (tracker + mirror step), the other tasks moved by SEA-RAFT optical flow
 *   (vision/raft.ts). Test only: the model downloads on first use and the measure is not validated.
 */
import { PROFILE } from '../config';
import { ALGORITHM_VERSION, type AnalysisResult } from '../core';
import type { RaftEngine } from './raft';

export type TrackMethod = 'v060' | 'v050' | 'raft';

export const DEFAULT_METHOD: TrackMethod = 'v060';

export const METHOD_VERSION: Readonly<Record<TrackMethod, string>> = Object.freeze({
  v060: ALGORITHM_VERSION,
  v050: '0.5.0',
  raft: `${ALGORITHM_VERSION}-raft`,
});

export const METHOD_LABEL: Readonly<Record<TrackMethod, string>> = Object.freeze({
  v060: `기본 (v${ALGORITHM_VERSION})`,
  v050: '이전 (v0.5.0)',
  raft: 'SEA-RAFT 혼합 (시험)',
});

/** Tasks the hybrid measures with SEA-RAFT (eye closure stays with the tracker and the mirror step). */
export const RAFT_TASKS: ReadonlySet<string> = new Set(['brow', 'smile', 'snarl', 'pucker']);

/** Frames per task the hybrid runs SEA-RAFT on in a video assessment (each is one model run). */
export const RAFT_VIDEO_FRAMES = 8;

/** The method to measure with: the profile's choice in the research build, else the default. */
export const methodOf = (p: { trackMethod?: TrackMethod } | null | undefined): TrackMethod =>
  PROFILE === 'research' ? (p?.trackMethod ?? DEFAULT_METHOD) : DEFAULT_METHOD;

/** What a SEA-RAFT run took, shown with the result (on-device test). */
export interface RaftRun {
  backend: 'webgpu' | 'wasm';
  pairs: number;
  /** The first run (model warm-up, shader compilation) and the mean of the others. */
  firstMs: number;
  msPerPair: number;
  /** Set when SEA-RAFT could not run and the default method measured instead. */
  error?: string;
}

export const raftRunText = (x: RaftRun): string =>
  x.error
    ? `SEA-RAFT를 실행하지 못해 기본 방식으로 측정했습니다 (${x.error}).`
    : `SEA-RAFT(시험): ${x.backend === 'webgpu' ? 'GPU(WebGPU)' : 'CPU(WASM)'}로 ${x.pairs}쌍, 쌍당 ${(x.msPerPair / 1000).toFixed(2)}초` +
      ` (첫 쌍 ${(x.firstMs / 1000).toFixed(1)}초).`;

/**
 * Runs the SEA-RAFT step of the hybrid on a tracker whose tasks were picked (trackTask). Returns the run summary;
 * on failure the tracker's own points stay and `error` is set (record the result as the default method then).
 */
export async function runRaft(
  tk: { addFlow(task: string, e: RaftEngine, onPair?: () => void): Promise<number>; flowPairs(task: string): number },
  onStatus: (text: string) => void,
): Promise<RaftRun> {
  const tasks = [...RAFT_TASKS];
  const total = tasks.reduce((n, t) => n + tk.flowPairs(t), 0);
  try {
    const { loadRaft } = await import('./raft');
    const engine = await loadRaft((f) => onStatus(`SEA-RAFT 모델 받는 중 ${Math.round(100 * f)}% (처음 한 번, 약 80 MB)`));
    const ms: number[] = [];
    let t0 = performance.now();
    onStatus(`SEA-RAFT 분석 중 0/${total}`);
    for (const t of tasks)
      await tk.addFlow(t, engine, () => {
        const now = performance.now();
        ms.push(now - t0);
        t0 = now;
        onStatus(`SEA-RAFT 분석 중 ${ms.length}/${total}`);
      });
    const rest = ms.slice(1);
    const mean = (a: number[]) => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0);
    return { backend: engine.backend, pairs: ms.length, firstMs: ms[0] ?? 0, msPerPair: rest.length ? mean(rest) : mean(ms) };
  } catch (e) {
    console.warn('SEA-RAFT failed', e);
    return { backend: 'wasm', pairs: 0, firstMs: 0, msPerPair: 0, error: e instanceof Error ? e.message : String(e) };
  }
}

const RUNS_KV = 'raftRuns';

/** Keeps what the SEA-RAFT step took for a saved session (on this device, outside the sealed record; last 30). */
export async function saveRaftRun(sessionId: string, run: RaftRun): Promise<void> {
  try {
    const { db } = await import('../data/db');
    const prev = (await db.getKv<Record<string, RaftRun>>(RUNS_KV)) ?? {};
    const all = Object.entries({ ...prev, [sessionId]: run }).slice(-30);
    await db.setKv(RUNS_KV, Object.fromEntries(all));
  } catch (e) {
    console.warn('SEA-RAFT run not kept', e);
  }
}

export async function getRaftRun(sessionId: string): Promise<RaftRun | undefined> {
  const { db } = await import('../data/db');
  return (await db.getKv<Record<string, RaftRun>>(RUNS_KV))?.[sessionId];
}

/** The result as recorded under `method` (the algorithm version it was measured with). */
export function withMethod(r: AnalysisResult, method: TrackMethod): AnalysisResult {
  return method === 'v060' ? r : { ...r, algorithm: { ...r.algorithm, version: METHOD_VERSION[method] } };
}
