/**
 * Single-photo static asymmetry (FPA-STILL).
 *
 * For photographs that have no same-session rest reference (e.g. a published
 * photo series with one expression per day) movement excursion cannot be
 * measured. Instead, side-to-side differences are measured within the photo
 * itself, in the spirit of photograph-based tools such as Emotrics: brow
 * height, palpebral fissure, oral commissure height and nasal ala height,
 * each referenced to the interpupillary line of the same photo.
 * Differences are signed so that + always means "affected side worse".
 */
import { faceFrame, toFaceCoords, toPixels } from './geometry';
import { SIDE, otherSide } from './landmarks';
import { browLevel, eyeAperture, irisDiameter, midlineX, mouthCorner } from './measures';
import { assessFrame } from './quality';
import { clamp, mean } from './stats';
import type { FrameObservation, FrameQuality, Side, Vec2 } from './types';

export const STILL_ALGORITHM = { id: 'FPA-STILL', version: '0.1.0' } as const;

export type StillExpression = 'rest' | 'brow' | 'eyeClose' | 'smile' | 'mouthOpen' | 'mixed';
export type StillRegion = 'brow' | 'eye' | 'mouth' | 'midface';
export const STILL_REGIONS: readonly StillRegion[] = ['brow', 'eye', 'mouth', 'midface'];

/** Regions whose asymmetry is informative for each photographed expression. */
export const RELEVANT_REGIONS: Readonly<Record<StillExpression, readonly StillRegion[]>> = {
  rest: ['brow', 'eye', 'mouth', 'midface'],
  brow: ['brow'],
  eyeClose: ['eye'],
  smile: ['mouth', 'midface'],
  mouthOpen: ['mouth'],
  mixed: ['brow', 'mouth'],
};

/** PROVISIONAL: |difference| band cut-offs in mm (0 symmetric, 1 slight, 2 obvious, 3 marked). */
export const STILL_BANDS_MM = [2, 4, 7] as const;
/** Region symmetry reaches 0 at this absolute difference (mm). */
export const STILL_ZERO_MM = 10;
/** Nominal adult interpupillary distance, used when no iris scale is usable. */
export const NOMINAL_IPD_MM = 63;

export interface SideStill {
  /** Pupil line to mean upper-brow height (+ = above pupils). */
  browHeight: number;
  /** Marginal reflex distances: pupil to upper / lower lid margin. */
  mrd1: number;
  mrd2: number;
  /** Palpebral fissure height (mean of three lid-pair distances). */
  fissure: number;
  /** Oral commissure below the pupil line. */
  commissureHeight: number;
  /** Oral commissure distance from the facial midline. */
  commissureLateral: number;
  /** Nasal ala below the pupil line. */
  alaHeight: number;
}

export interface StillRegionResult {
  /** Signed difference in mm, + = affected side worse. */
  diffMm: number;
  band: 0 | 1 | 2 | 3;
  /** 100 × (1 − |diff| / STILL_ZERO_MM), clamped to 0..100. */
  symmetry: number;
  relevant: boolean;
  excluded: boolean;
}

export interface StillAnalysis {
  algorithm: { id: string; version: string };
  expression: StillExpression;
  affectedSide: Side;
  quality: FrameQuality;
  /** mm per face unit; `scaleSource` says whether it came from the iris or the nominal IPD. */
  mmPerUnit: number;
  scaleSource: 'iris' | 'nominal';
  sides: Record<Side, SideStill>;
  regions: Record<StillRegion, StillRegionResult>;
  /** Affected / healthy commissure distance from the midline (< 1: affected corner drawn medially). */
  mouthLateralRatio: number;
  /** Tilt of the inter-commissure line vs. the pupil line, + = affected corner lower (deg). */
  commissureTiltDeg: number;
  /** Mean symmetry of relevant, non-excluded regions (null if none). */
  symmetryIndex: number | null;
  /** Side that looks weaker from the relevant regions (null if ambiguous). */
  suggestedAffectedSide: Side | null;
  /** Landmarks in image pixels [x0, y0, ...] for overlays (rounded to 0.1 px). */
  keyframe: { width: number; height: number; points: number[] };
}

const band = (mm: number): 0 | 1 | 2 | 3 => {
  const a = Math.abs(mm);
  return a < STILL_BANDS_MM[0] ? 0 : a < STILL_BANDS_MM[1] ? 1 : a < STILL_BANDS_MM[2] ? 2 : 3;
};

function measureSide(F: readonly Vec2[], s: Side, mid: number): SideStill {
  const idx = SIDE[s];
  const pupil = F[s === 'right' ? 468 : 473]!;
  const upper = F[idx.lidPairs[1]![0]]!;
  const lower = F[idx.lidPairs[1]![1]]!;
  const corner = mouthCorner(F, s);
  return {
    browHeight: pupil.y - browLevel(F, s),
    mrd1: pupil.y - upper.y,
    mrd2: lower.y - pupil.y,
    fissure: eyeAperture(F, s),
    commissureHeight: corner.y - pupil.y,
    commissureLateral: Math.abs(corner.x - mid),
    alaHeight: mean(idx.ala.map((i) => F[i]!.y)) - pupil.y,
  };
}

/** Signed differences with `aff` as the affected side (+ = affected worse), in face units. */
function signedDiffs(S: Record<Side, SideStill>, aff: Side): Record<StillRegion, number> {
  const A = S[aff];
  const H = S[otherSide(aff)];
  return {
    brow: H.browHeight - A.browHeight,
    eye: A.fissure - H.fissure,
    mouth: A.commissureHeight - H.commissureHeight,
    midface: A.alaHeight - H.alaHeight,
  };
}

export interface StillOptions {
  affectedSide: Side;
  expression: StillExpression;
  /** Regions known to be unusable in this photo (occlusion, cropping). */
  exclude?: readonly StillRegion[];
}

/** Returns null when no face (478-point topology) is present. */
export function analyzeStill(obs: FrameObservation, opts: StillOptions): StillAnalysis | null {
  if (obs.landmarks.length < 478 * 3) return null;
  const quality = assessFrame(obs);
  const px = toPixels(obs);
  const F = toFaceCoords(faceFrame(px), px);
  const mid = midlineX(F);
  const S = { right: measureSide(F, 'right', mid), left: measureSide(F, 'left', mid) };

  // Iris landmarks are guessed when the eyes are shut; use the nominal IPD then.
  const irisD = (irisDiameter(F, 'left') + irisDiameter(F, 'right')) / 2;
  const irisOk = opts.expression !== 'eyeClose' && irisD >= 0.12 && irisD <= 0.3;
  const mmPerUnit = irisOk ? 11.7 / irisD : NOMINAL_IPD_MM;

  const exclude = new Set(opts.exclude ?? []);
  const relevant = new Set(RELEVANT_REGIONS[opts.expression]);
  const d = signedDiffs(S, opts.affectedSide);
  const regions = {} as Record<StillRegion, StillRegionResult>;
  for (const r of STILL_REGIONS) {
    const mm = d[r] * mmPerUnit;
    regions[r] = {
      diffMm: mm,
      band: band(mm),
      symmetry: Math.round(100 * clamp(1 - Math.abs(mm) / STILL_ZERO_MM, 0, 1)),
      relevant: relevant.has(r),
      excluded: exclude.has(r),
    };
  }
  const used = STILL_REGIONS.filter((r) => regions[r].relevant && !regions[r].excluded);
  const symmetryIndex = used.length ? Math.round(mean(used.map((r) => regions[r].symmetry))) : null;

  // Evidence for "left is the weaker side" from the usable regions (mm, capped).
  const dl = signedDiffs(S, 'left');
  const evidence = used.reduce((s, r) => s + clamp(dl[r] * mmPerUnit, -STILL_ZERO_MM, STILL_ZERO_MM), 0);
  const suggestedAffectedSide: Side | null = Math.abs(evidence) < STILL_BANDS_MM[0] ? null : evidence > 0 ? 'left' : 'right';

  const aff = opts.affectedSide;
  const cA = mouthCorner(F, aff);
  const cH = mouthCorner(F, otherSide(aff));
  const r1 = (x: number) => Math.round(x * 10) / 10;
  return {
    algorithm: { ...STILL_ALGORITHM },
    expression: opts.expression,
    affectedSide: aff,
    quality,
    mmPerUnit,
    scaleSource: irisOk ? 'iris' : 'nominal',
    sides: {
      right: scaleSide(S.right, mmPerUnit),
      left: scaleSide(S.left, mmPerUnit),
    },
    regions,
    mouthLateralRatio: S[aff].commissureLateral / Math.max(1e-6, S[otherSide(aff)].commissureLateral),
    commissureTiltDeg: (Math.atan2(cA.y - cH.y, Math.abs(cA.x - cH.x)) * 180) / Math.PI,
    symmetryIndex,
    suggestedAffectedSide,
    keyframe: { width: obs.width, height: obs.height, points: px.flatMap((p) => [r1(p.x), r1(p.y)]) },
  };
}

function scaleSide(s: SideStill, k: number): SideStill {
  return {
    browHeight: s.browHeight * k,
    mrd1: s.mrd1 * k,
    mrd2: s.mrd2 * k,
    fissure: s.fissure * k,
    commissureHeight: s.commissureHeight * k,
    commissureLateral: s.commissureLateral * k,
    alaHeight: s.alaHeight * k,
  };
}
