/**
 * Exercise and re-assessment reminders (SRS-RHB-017). The app has no server, so the reliable route is the phone's own
 * calendar: an .ics file with repeating events and alarms (Samsung Calendar, iPhone), or a Google Calendar event
 * link. An installed Android app can also show a notification (ui/notify.ts, best effort), and the home screen shows
 * when a reminder time has passed without the routine done.
 *
 * Calendar titles are neutral ("얼굴 운동 시간") so a shared or synced calendar does not name the condition.
 */
import type { RehabLog } from '../data/types';

export interface Reminders {
  /** Daily exercise times, "HH:MM", sorted, at most 3. */
  exercise: string[];
  /** Weekly re-assessment: weekday 0 (Sun)–6 and "HH:MM", or none. */
  assess: { day: number; time: string } | null;
  /** Show notifications from the installed app as well (best effort). */
  notify: boolean;
}

export const DEFAULT_REMINDERS: Reminders = { exercise: ['09:00', '20:00'], assess: { day: 1, time: '10:00' }, notify: false };
export const MAX_EXERCISE_TIMES = 3;
export const WEEKDAY_LABEL = ['일', '월', '화', '수', '목', '금', '토'] as const;
const ICS_DAY = ['SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'] as const;

export const EXERCISE_TITLE = '얼굴 운동 시간';
export const ASSESS_TITLE = '얼굴 움직임 평가';

const TIME_RE = /^([01]\d|2[0-3]):([0-5]\d)$/;
export const isTime = (t: string): boolean => TIME_RE.test(t);

/** Valid, unique, sorted times (at most MAX_EXERCISE_TIMES). */
export function cleanTimes(times: readonly string[]): string[] {
  return [...new Set(times.filter(isTime))].sort().slice(0, MAX_EXERCISE_TIMES);
}

/** "09:00" → "오전 9:00", "20:30" → "오후 8:30". */
export function timeLabel(t: string): string {
  const [h, m] = t.split(':').map(Number) as [number, number];
  const pm = h >= 12;
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${pm ? '오후' : '오전'} ${h12}:${String(m).padStart(2, '0')}`;
}

const pad = (n: number) => String(n).padStart(2, '0');
const dateStamp = (d: Date) => `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`;
const utcStamp = (d: Date) =>
  `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`;

/** Folds a content line at 75 octets (RFC 5545 §3.1), never inside a UTF-8 character. */
export function foldLine(line: string): string {
  const enc = new TextEncoder();
  const parts: string[] = [];
  let cur = '';
  let bytes = 0;
  for (const ch of line) {
    const n = enc.encode(ch).length;
    const limit = parts.length === 0 ? 75 : 74; // continuation lines start with one space
    if (bytes + n > limit) {
      parts.push(cur);
      cur = '';
      bytes = 0;
    }
    cur += ch;
    bytes += n;
  }
  parts.push(cur);
  return parts.join('\r\n ');
}

const esc = (s: string) => s.replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');

/** The next date (today included) that falls on `weekday`. */
function nextWeekday(from: Date, weekday: number): Date {
  const d = new Date(from.getFullYear(), from.getMonth(), from.getDate());
  d.setDate(d.getDate() + ((weekday - d.getDay() + 7) % 7));
  return d;
}

/**
 * The reminders as an iCalendar file. Times are floating (no time zone), so they ring at that local time on the
 * phone. Stable UIDs, so importing again updates the same events in calendars that support it.
 */
export function remindersIcs(r: Reminders, appUrl: string, now: Date = new Date()): string {
  const lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Facial Palsy Care//Reminders//KO', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH'];
  const event = (uid: string, start: Date, time: string, rrule: string, title: string, text: string, minutes: number) => {
    const [h, m] = time.split(':');
    lines.push(
      'BEGIN:VEVENT',
      `UID:${uid}@facial-palsy-care`,
      `DTSTAMP:${utcStamp(now)}`,
      `DTSTART:${dateStamp(start)}T${h}${m}00`,
      `DURATION:PT${minutes}M`,
      `RRULE:${rrule}`,
      `SUMMARY:${esc(title)}`,
      `DESCRIPTION:${esc(`${text} ${appUrl}`)}`,
      `URL:${appUrl}`,
      'BEGIN:VALARM',
      'ACTION:DISPLAY',
      `DESCRIPTION:${esc(title)}`,
      'TRIGGER:PT0M',
      'END:VALARM',
      'END:VEVENT',
    );
  };
  for (const t of cleanTimes(r.exercise)) {
    event(`exercise-${t.replace(':', '')}`, now, t, 'FREQ=DAILY', EXERCISE_TITLE, '오늘의 얼굴 운동을 해 주세요.', 15);
  }
  if (r.assess && isTime(r.assess.time)) {
    event(
      'assess-weekly',
      nextWeekday(now, r.assess.day),
      r.assess.time,
      `FREQ=WEEKLY;BYDAY=${ICS_DAY[r.assess.day]}`,
      ASSESS_TITLE,
      '일주일에 한 번, 같은 장소와 조명에서 얼굴 평가를 해 주세요.',
      5,
    );
  }
  lines.push('END:VCALENDAR');
  return lines.map(foldLine).join('\r\n') + '\r\n';
}

/** A Google Calendar "new event" link with the same repeating event (opens Google Calendar; nothing is sent otherwise). */
export function googleCalendarLink(
  title: string,
  time: string,
  rrule: string,
  details: string,
  now: Date = new Date(),
  minutes = 15,
): string {
  const [h, m] = time.split(':').map(Number) as [number, number];
  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), h, m);
  const end = new Date(start.getTime() + minutes * 60000);
  const local = (d: Date) => `${dateStamp(d)}T${pad(d.getHours())}${pad(d.getMinutes())}00`;
  const q = new URLSearchParams({
    action: 'TEMPLATE',
    text: title,
    dates: `${local(start)}/${local(end)}`,
    details,
    recur: `RRULE:${rrule}`,
  });
  return `https://calendar.google.com/calendar/render?${q.toString()}`;
}

/** Today's exercise reminder state for the home screen: the last reminder time already passed, if nothing was done today. */
export function missedReminder(r: Reminders | undefined, logs: readonly RehabLog[], today: string, now: Date = new Date()): string | null {
  if (!r) return null;
  const hhmm = `${pad(now.getHours())}:${pad(now.getMinutes())}`;
  const passed = cleanTimes(r.exercise).filter((t) => t <= hhmm);
  if (!passed.length || logs.some((l) => l.date === today)) return null;
  return passed[passed.length - 1]!;
}
