/**
 * Restore from the app's own JSON export (exportJson, format fpc-export/1): records are merged by id, sealed
 * records must verify before they are added, and nothing already on this device is overwritten.
 */
import { verify } from './integrity';
import type { ClinicianRating, Etiology, RehabLog, SessionRecord, SynkRecord } from './types';
import type { Side } from '../core';
import type { CheckinRecord } from '../rehab/checkin';

export const EXPORT_FORMAT = 'fpc-export/1';

/** Largest backup file read (a year of daily assessments is a few MB); bigger files are refused unread. */
export const MAX_IMPORT_BYTES = 50 * 1024 * 1024;

export interface ImportSubject {
  affectedSide: Side;
  onsetDate: string;
  etiology: Etiology;
  birthYear: number | null;
}

export interface SealedPart<T> {
  add: T[];
  /** Already on this device with the same seal. */
  same: number;
  /** Same id on this device but a different seal: the local record is kept. */
  conflict: number;
  /** Malformed, or the seal does not match the content (altered or damaged): not imported. */
  invalid: number;
}

export interface PlainPart<T> {
  add: T[];
  same: number;
  invalid: number;
}

export interface ImportPlan {
  exportedAt: string | null;
  /** Research subject code the file was exported from (null = someone's own records). */
  subjectCode: string | null;
  appVersion: string | null;
  subject: ImportSubject | null;
  sessions: SealedPart<SessionRecord>;
  synk: SealedPart<SynkRecord>;
  ratings: PlainPart<ClinicianRating>;
  rehab: PlainPart<RehabLog>;
  /** Weekly patient checks (rehab/checkin.ts). */
  checkins: PlainPart<CheckinRecord>;
}

export interface LocalRecords {
  sessions: readonly SessionRecord[];
  synk: readonly SynkRecord[];
  ratings: readonly ClinicianRating[];
  rehab: readonly RehabLog[];
  checkins?: readonly CheckinRecord[];
}

/** A file that cannot be imported at all; `message` is shown to the user. */
export class ImportError extends Error {}

type Obj = Record<string, unknown>;
const isObj = (v: unknown): v is Obj => typeof v === 'object' && v !== null && !Array.isArray(v);
const str = (v: unknown): v is string => typeof v === 'string' && v.length > 0;
const list = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const SIDES: readonly string[] = ['left', 'right'];
const ETIOLOGIES: readonly string[] = ['bell', 'ramsayHunt', 'postSurgical', 'trauma', 'other', 'unknown'];

function sealedShape(v: unknown): v is Obj & { id: string; integrity: { hash: string } } {
  return isObj(v) && v.schema === 1 && str(v.id) && str(v.createdAt) && isObj(v.integrity) && str(v.integrity.hash);
}

/** Drops the fields exportJson adds next to the sealed content. */
function unwrap(v: Obj): Obj {
  const { integrityVerified: _, ...rest } = v;
  return rest;
}

async function sealedPart<T extends { id: string; integrity: { hash: string } }>(
  items: unknown[],
  local: readonly T[],
  valid: (v: Obj) => boolean,
): Promise<SealedPart<T>> {
  const have = new Map(local.map((r) => [r.id, r.integrity.hash]));
  const seen = new Set<string>();
  const out: SealedPart<T> = { add: [], same: 0, conflict: 0, invalid: 0 };
  for (const raw of items) {
    if (!sealedShape(raw) || !valid(raw)) {
      out.invalid++;
      continue;
    }
    const rec = unwrap(raw) as unknown as T;
    if (seen.has(rec.id)) continue;
    seen.add(rec.id);
    if (!(await verify(rec))) out.invalid++;
    else if (!have.has(rec.id)) out.add.push(rec);
    else if (have.get(rec.id) === rec.integrity.hash) out.same++;
    else out.conflict++;
  }
  return out;
}

function plainPart<T extends { id: string }>(items: unknown[], local: readonly T[], valid: (v: Obj) => boolean): PlainPart<T> {
  const have = new Set(local.map((r) => r.id));
  const out: PlainPart<T> = { add: [], same: 0, invalid: 0 };
  for (const raw of items) {
    if (!isObj(raw) || !str(raw.id) || !valid(raw)) {
      out.invalid++;
      continue;
    }
    if (have.has(raw.id)) out.same++;
    else {
      have.add(raw.id);
      out.add.push(raw as unknown as T);
    }
  }
  return out;
}

function subjectOf(v: unknown): ImportSubject | null {
  if (!isObj(v) || !SIDES.includes(v.affectedSide as string) || !str(v.onsetDate) || !/^\d{4}-\d{2}-\d{2}$/.test(v.onsetDate)) return null;
  return {
    affectedSide: v.affectedSide as Side,
    onsetDate: v.onsetDate,
    etiology: (ETIOLOGIES.includes(v.etiology as string) ? v.etiology : 'unknown') as Etiology,
    birthYear: typeof v.birthYear === 'number' && Number.isInteger(v.birthYear) ? v.birthYear : null,
  };
}

/** Reads an export file and works out what would be added. Throws ImportError for files that are not an export. */
export async function planImport(text: string, local: LocalRecords): Promise<ImportPlan> {
  let data: unknown;
  try {
    data = JSON.parse(text.replace(/^﻿/, ''));
  } catch {
    throw new ImportError('JSON 파일이 아니거나 내용이 깨져 있습니다.');
  }
  if (!isObj(data) || data.format !== EXPORT_FORMAT) {
    throw new ImportError('이 앱의 ‘전체 기록 내보내기(JSON)’ 파일이 아닙니다. CSV 요약 파일은 가져올 수 없습니다.');
  }
  const app = isObj(data.app) ? data.app : null;
  return {
    exportedAt: str(data.exportedAt) ? data.exportedAt : null,
    subjectCode: str(data.subjectCode) ? data.subjectCode : null,
    appVersion: app && str(app.version) ? app.version : null,
    subject: subjectOf(data.subject),
    sessions: await sealedPart<SessionRecord>(list(data.sessions), local.sessions, (v) => isObj(v.analysis) && isObj(v.profileSnapshot)),
    synk: await sealedPart<SynkRecord>(list(data.synkinesisFinder), local.synk, (v) => isObj(v.result) && isObj(v.profileSnapshot)),
    ratings: plainPart<ClinicianRating>(list(data.clinicianRatings), local.ratings, (v) => str(v.sessionId) && str(v.createdAt)),
    rehab: plainPart<RehabLog>(
      list(data.rehabLogs),
      local.rehab,
      (v) => str(v.date) && str(v.at) && str(v.exerciseId) && typeof v.durationSec === 'number',
    ),
    checkins: plainPart<CheckinRecord>(
      list(data.checkins),
      local.checkins ?? [],
      (v) => str(v.at) && str(v.date) && /^\d{4}-\d{2}-\d{2}$/.test(v.date) && str(v.version) && isObj(v.answers),
    ),
  };
}

export const importCount = (p: ImportPlan): number =>
  p.sessions.add.length + p.synk.add.length + p.ratings.add.length + p.rehab.add.length + p.checkins.add.length;

/** Fields of the file's subject that differ from the current profile. */
export function subjectDiff(p: ImportPlan, profile: ImportSubject): (keyof ImportSubject)[] {
  const s = p.subject;
  if (!s) return [];
  return (['affectedSide', 'onsetDate', 'etiology', 'birthYear'] as const).filter((k) => s[k] !== profile[k]);
}
