/**
 * Core data types of the measurement engine.
 *
 * The `core/` directory is the SaMD software item "FPA-CORE": it is pure,
 * deterministic TypeScript with no DOM, network, storage or ML-runtime
 * dependency. Given the same landmark input it always yields the same output.
 */

/** Anatomical side of the patient (never the side of the screen). */
export type Side = 'left' | 'right';

export type MovementTaskId = 'brow' | 'eyeClose' | 'smile' | 'snarl' | 'pucker';
export type TaskId = 'rest' | MovementTaskId;

export const MOVEMENT_TASKS: readonly MovementTaskId[] = ['brow', 'eyeClose', 'smile', 'snarl', 'pucker'];
/** Movements the exercise mirror's live guide can measure: the assessed ones plus the cheek puff (rehab only). */
export type LiveTaskId = MovementTaskId | 'cheekPuff';

export interface Vec2 {
  x: number;
  y: number;
}

/** Head pose in degrees. */
export interface Pose {
  yaw: number;
  pitch: number;
  roll: number;
}

/** One analysed camera frame, as delivered by the vision layer. */
export interface FrameObservation {
  /** Timestamp in ms (monotonic within a recording). */
  t: number;
  /** Source image size in pixels (landmarks are normalised to it). */
  width: number;
  height: number;
  /** Flattened normalised landmarks [x0, y0, z0, x1, ...]; x,y in [0,1]. Empty if no face. */
  landmarks: ArrayLike<number>;
  /** Head pose from the landmarker's facial transformation matrix, if available. */
  pose?: Pose;
  /**
   * Face-region luminance: 0–255 mean, |L−R|/(L+R) left/right imbalance, and (since 2026-10-13) the signed balance in
   * image terms: `horiz` + = the image's right half brighter (the patient's left side), `vert` + = the upper face brighter.
   */
  luminance?: { mean: number; asymmetry: number; horiz?: number; vert?: number };
  /** Tracked frames: share (0–1) of the face points tracking kept (the rest fell back to the detection). */
  trackKept?: number;
  /** Tracked frames: contrast-normalised edge strength and grain of the face crop (vision/sharpness.ts). */
  sharpness?: { sharp: number; noise: number };
  /** Optional blendshape scores (categoryName → 0..1), kept for research only. */
  blendshapes?: Record<string, number>;
  /** Tracked frames: share (0–1) of each eye's lid points that tracking kept (the rest are the detection's). */
  lidTracked?: SidePair;
  /**
   * Eye closure fraction of each eye measured on its own mirror composite (vision/mirror.ts): the half of the face
   * holding that eye mirrored across the midline, so the landmark model sees a symmetric face and has no other eye to
   * pull towards. Used for an eye whose lid points were not tracked (FPA-GEOM 0.5.0).
   */
  mirrorClosure?: { left: number | null; right: number | null };
}

export interface SidePair {
  right: number;
  left: number;
}

export type QualityIssue = 'noFace' | 'yaw' | 'pitch' | 'roll' | 'tooFar' | 'outOfFrame' | 'dark' | 'bright' | 'unevenLight';

export interface FrameQuality {
  ok: boolean;
  issues: QualityIssue[];
  pose: Pose;
  /** Inter-eye-centre distance in pixels. */
  eyeDistancePx: number;
}

export interface TaskQuality {
  framesTotal: number;
  framesValid: number;
  framesUsed: number;
  /** Most frequent rejection reasons, for user feedback. */
  issueCounts: Partial<Record<QualityIssue, number>>;
  /** Median absolute head pose over used frames (deg). */
  medianAbsYaw: number;
  medianAbsPitch: number;
  medianAbsRoll: number;
  /** RMS residual of the rigid alignment to the rest reference (face units). */
  alignmentResidual: number;
  /** Capture conditions of the used frames (SRS-QC-010); absent in records made before 2026-10-13. */
  conditions?: StepConditions;
}

/** Medians over the frames a step used (core/conditions.ts stepConditions). */
export interface StepConditions {
  /** Face-box centre minus the image centre, fraction of the image width / height (+ = image right / down). */
  offsetX: number;
  offsetY: number;
  /** Face width (temple to temple) as a fraction of the image width. */
  faceWidth: number;
  /** Inter-eye-centre distance in pixels. */
  eyePx: number;
  /** Face luminance 0–255 and its signed balance (FrameObservation.luminance). */
  light?: { mean: number; horiz: number; vert: number };
  /** Share of face points kept by tracking (0–1); absent for untracked detections. */
  trackKept?: number;
  /** Face-crop sharpness and grain; absent where not measured. */
  sharp?: number;
  noise?: number;
}

export interface RestMeasurement {
  /** Palpebral fissure height, affected / healthy (1 = symmetric). */
  eyeApertureRatio: number;
  /** Brow level difference, affected − healthy, + = affected lower (face units). */
  browDrop: number;
  /** Oral commissure level difference, + = affected corner lower (face units). */
  mouthCornerDrop: number;
  /** Mid-face (nasal ala + cheek) level difference, + = affected lower. */
  midfaceDrop: number;
  /** Lip centre shift towards the healthy side (face units). */
  mouthDeviation: number;
  /** Sunnybrook-style resting symmetry items (estimated). */
  items: { eye: 0 | 1; cheek: 0 | 1 | 2; mouth: 0 | 1 };
}

export interface TaskMeasurement {
  task: MovementTaskId;
  /** Primary movement per side (face units, or closure fraction for eyeClose). */
  excursion: SidePair;
  /** Excursion in millimetres (if iris scale available and task is metric). */
  excursionMm?: SidePair;
  /** Affected / healthy excursion, clamped to [0, 2]. */
  ratio: number;
  /** Involuntary movement in a non-target region, per side. */
  offTarget: SidePair;
  /** max(0, offTarget_affected − offTarget_healthy). */
  synkinesisIndex: number;
  /** Sunnybrook-style voluntary movement grade 1–5 (estimated). */
  grade: 1 | 2 | 3 | 4 | 5;
  /** Sunnybrook-style synkinesis grade 0–3 (estimated, experimental). */
  synkinesisGrade: 0 | 1 | 2 | 3;
  /** False when the healthy side did not move enough to form a valid ratio. */
  reliable: boolean;
  /** Task-specific extra measures (e.g. residual eye gap). */
  extras: Record<string, number>;
  quality: TaskQuality;
}

export type HouseBrackmannGrade = 1 | 2 | 3 | 4 | 5 | 6;

export interface Scores {
  restScore: number;
  voluntaryScore: number;
  synkinesisScore: number;
  /** Sunnybrook-compatible composite 0–100 (estimated). */
  composite: number;
  /** House–Brackmann grade (estimated, rule-based). */
  houseBrackmann: { grade: HouseBrackmannGrade; ruleId: string };
  /** Facial Function Index: mean of capped movement ratios × 100. */
  functionIndex: number;
  /** Region-level movement ratios × 100 (capped at 100). */
  regional: { forehead: number; eye: number; midface: number; mouth: number };
  eyeClosureComplete: boolean;
  /** SC-0.3.0: the paralysed eye's lid gap left open beyond the healthy eye's at gentle closure, mm (0.1 mm). */
  eyeGapMm?: number;
}

export type AnalysisWarning =
  | 'REST_UNSTABLE'
  | 'REST_NOT_NEUTRAL'
  | 'SIDE_MISMATCH'
  | 'LOW_EFFORT'
  | 'HIGH_ALIGNMENT_RESIDUAL'
  | 'NO_IRIS_SCALE'
  /** Smile with the jaw opened (chin lowered past AGGREGATION.maxJawDrop): the weak corner reads larger. */
  | 'JAW_OPEN';

export type AnalysisError = 'REST_INSUFFICIENT' | 'TASK_INSUFFICIENT';

export interface AnalysisResult {
  algorithm: { id: string; version: string; scoringVersion: string };
  status: 'complete' | 'incomplete' | 'failed';
  errors: { code: AnalysisError; task?: TaskId }[];
  warnings: { code: AnalysisWarning; task?: TaskId }[];
  affectedSide: Side;
  /** Side whose movement is weaker according to the measurements. */
  suggestedAffectedSide: Side | null;
  /** How clearly that side is weaker: 'strong' lets the assessment recalculate with it (SRS-ALG-011). */
  suggestedSideStrength?: 'strong' | 'weak' | null;
  mmPerUnit: number | null;
  restQuality: TaskQuality | null;
  rest: RestMeasurement | null;
  tasks: Partial<Record<MovementTaskId, TaskMeasurement>>;
  scores: Scores | null;
  /**
   * Geometry needed to reproduce every metric and to draw a de-identified
   * wireframe: the median rest reference and one representative frame per
   * task, both in rest-image pixel space. No images are ever stored.
   */
  keyframes: {
    width: number;
    height: number;
    rest: number[];
    tasks: Partial<Record<MovementTaskId, number[]>>;
  } | null;
}
