/**
 * Small responsive line chart (single y axis) with crosshair tooltip and
 * keyboard navigation. Follows the dataviz reference specs: 2px lines, ≥8px
 * markers with a 2px surface ring, hairline solid grid, text in ink tokens.
 *
 * The x axis follows the assessments rather than the calendar from day 0 (assessmentAxis): it starts at the first
 * point, keeps real time between neighbours, cuts long empty stretches short (break mark on the axis, dashed line)
 * and gives points on the same x (same-day assessments) a place of their own.
 */
import { useMemo, useRef, useState } from 'preact/hooks';

export interface Series {
  id: string;
  label: string;
  color: string;
  points: { x: number; y: number }[];
}

interface Props {
  series: Series[];
  yMax: number;
  yTicks: number[];
  ySuffix?: string;
  xLabel: (x: number) => string;
  xTitle: string;
  height?: number;
  ariaLabel: string;
  /** Extra tooltip lines per x (e.g. estimated HB grade); `nth` tells same-x points apart (0 = the first). */
  extra?: (x: number, nth: number) => string | null;
}

const W = 340;
const M = { l: 34, r: 14, t: 12, b: 34 };
/** Space at both ends of the plot so the end markers stay clear of the edges. */
const PAD = 8;
/** A gap longer than CUT_FACTOR × the median gap between neighbours, and longer than CUT_MIN_DAYS, is cut short. */
const CUT_FACTOR = 3;
const CUT_MIN_DAYS = 7;
/** Width of a cut-short gap (room for the labels on both sides), and the least step between neighbours (viewBox units). */
const BREAK_W = 36;
const MIN_STEP = 12;
const LABEL_GAP = 34;

/**
 * Positions (0..width) of sorted x values; equal values are same-day assessments. Neighbours are MIN_STEP apart plus
 * real time; a gap longer than CUT_FACTOR × the median gap (and CUT_MIN_DAYS) is drawn BREAK_W wide instead, and
 * `cut[i]` marks the gap before point i as cut. Breaks take at most 30 % of the width.
 */
export function assessmentAxis(xs: readonly number[], width: number): { at: number[]; cut: boolean[] } {
  if (xs.length === 0) return { at: [], cut: [] };
  if (xs.length === 1) return { at: [width / 2], cut: [false] };
  const gaps = xs.slice(1).map((x, i) => x - xs[i]!);
  const real = gaps.filter((g) => g > 0).sort((a, b) => a - b);
  const median = real.length ? real[(real.length - 1) >> 1]! : 0;
  const limit = Math.max(CUT_MIN_DAYS, CUT_FACTOR * median);
  const cut = gaps.map((g) => g > limit);
  const nCut = cut.filter(Boolean).length;
  const nKeep = gaps.length - nCut;
  const breakW = nKeep === 0 ? width / nCut : nCut === 0 ? 0 : Math.min(BREAK_W, (width * 0.3) / nCut);
  const room = width - nCut * breakW;
  const days = gaps.reduce((a, g, i) => a + (cut[i] ? 0 : g), 0);
  const step = nKeep === 0 ? 0 : days > 0 ? Math.min(MIN_STEP, room / nKeep / 2) : room / nKeep;
  const perDay = days > 0 ? (room - nKeep * step) / days : 0;
  const at = [0];
  gaps.forEach((g, i) => at.push(at[i]! + (cut[i] ? breakW : step + g * perDay)));
  return { at, cut: [false, ...cut] };
}

interface Point {
  x: number;
  /** Which of the same-x points of its series (0 = the first). */
  nth: number;
}

const keyOf = (p: Point) => `${p.x}#${p.nth}`;

/** Each series' points with their same-x rank: series built from one list of sessions share these keys. */
function ranked(s: Series): (Point & { y: number })[] {
  const seen = new Map<number, number>();
  return s.points.map((p) => {
    const nth = seen.get(p.x) ?? 0;
    seen.set(p.x, nth + 1);
    return { x: p.x, y: p.y, nth };
  });
}

export function LineChart({ series, yMax, yTicks, ySuffix = '', xLabel, xTitle, height = 210, ariaLabel, extra }: Props) {
  const ref = useRef<SVGSVGElement>(null);
  const [hover, setHover] = useState<number | null>(null);
  const H = height;
  const lines = useMemo(() => series.map((s) => ({ s, pts: ranked(s) })), [series]);
  const axis = useMemo(() => {
    const byKey = new Map<string, Point>();
    for (const { pts } of lines) for (const p of pts) byKey.set(keyOf(p), { x: p.x, nth: p.nth });
    const events = [...byKey.values()].sort((a, b) => a.x - b.x || a.nth - b.nth);
    const { at, cut } = assessmentAxis(
      events.map((e) => e.x),
      W - M.l - M.r - 2 * PAD,
    );
    const where = new Map(events.map((e, i) => [keyOf(e), i]));
    const cutsBefore: number[] = [];
    cut.forEach((c, i) => cutsBefore.push((cutsBefore[i - 1] ?? 0) + (c ? 1 : 0)));
    return { events, at: at.map((v) => M.l + PAD + v), cut, where, cutsBefore };
  }, [lines]);
  const { events, at, cut, where, cutsBefore } = axis;
  const sy = (y: number) => M.t + (1 - y / yMax) * (H - M.t - M.b);
  const axisY = sy(0);

  // One label per day at the middle of its points, thinned so they do not overlap. First come the first and last
  // days, then the days where time picks up after a break, then the rest from left to right.
  const days: { x: number; at: number; rank: number }[] = [];
  events.forEach((e, i) => {
    const d = days[days.length - 1];
    if (d && d.x === e.x) d.at = (at[i - e.nth]! + at[i]!) / 2;
    else days.push({ x: e.x, at: at[i]!, rank: cut[i] ? 1 : 2 });
  });
  if (days.length) days[0]!.rank = days[days.length - 1]!.rank = 0;
  const labels: typeof days = [];
  for (const d of [...days].sort((a, b) => a.rank - b.rank || a.at - b.at))
    if (labels.every((l) => Math.abs(l.at - d.at) >= LABEL_GAP)) labels.push(d);

  const pick = (clientX: number) => {
    const svg = ref.current;
    if (!svg || events.length === 0) return;
    const r = svg.getBoundingClientRect();
    const vx = ((clientX - r.left) / r.width) * W;
    let best = 0;
    at.forEach((v, i) => {
      if (Math.abs(v - vx) < Math.abs(at[best]! - vx)) best = i;
    });
    setHover(best);
  };

  const he = hover !== null ? events[hover] : undefined;
  const hAt = hover !== null ? at[hover] : undefined;
  const tipLeftPct = hAt !== undefined ? (hAt / W) * 100 : 0;
  const sameDay = he ? events.filter((e) => e.x === he.x).length : 0;

  return (
    <div class="chart">
      <svg
        ref={ref}
        viewBox={`0 0 ${W} ${H}`}
        role="img"
        aria-label={ariaLabel}
        tabIndex={0}
        onPointerMove={(e) => pick(e.clientX)}
        onPointerDown={(e) => pick(e.clientX)}
        onPointerLeave={() => setHover(null)}
        onBlur={() => setHover(null)}
        onKeyDown={(e) => {
          if (events.length === 0) return;
          if (e.key === 'ArrowRight') setHover((h) => Math.min(events.length - 1, (h ?? -1) + 1));
          else if (e.key === 'ArrowLeft') setHover((h) => Math.max(0, (h ?? events.length) - 1));
          else return;
          e.preventDefault();
        }}
      >
        {yTicks.map((t) => (
          <g>
            <line x1={M.l} x2={W - M.r} y1={sy(t)} y2={sy(t)} stroke={t === 0 ? 'var(--axis)' : 'var(--grid)'} stroke-width="1" />
            <text x={M.l - 6} y={sy(t) + 4} text-anchor="end" font-size="11" fill="var(--muted)" class="tabular">
              {t}
              {ySuffix}
            </text>
          </g>
        ))}
        {cut.map((c, i) => {
          if (!c) return null;
          const bx = (at[i - 1]! + at[i]!) / 2;
          return (
            <g aria-hidden="true">
              <rect x={bx - 4} y={axisY - 5} width="8" height="10" fill="var(--surface)" />
              <line x1={bx - 5} y1={axisY + 4} x2={bx - 1} y2={axisY - 4} stroke="var(--muted)" stroke-width="1.25" />
              <line x1={bx + 1} y1={axisY + 4} x2={bx + 5} y2={axisY - 4} stroke="var(--muted)" stroke-width="1.25" />
            </g>
          );
        })}
        {labels.map((d) => (
          <text x={d.at} y={H - M.b + 16} text-anchor="middle" font-size="11" fill="var(--muted)" class="tabular">
            {xLabel(d.x)}
          </text>
        ))}
        <text x={(M.l + W - M.r) / 2} y={H - 4} text-anchor="middle" font-size="11" fill="var(--muted)">
          {xTitle}
        </text>
        {hAt !== undefined && <line x1={hAt} x2={hAt} y1={M.t} y2={H - M.b} stroke="var(--axis)" stroke-width="1" />}
        {lines.map(({ s, pts }) => {
          const xy = pts.map((p) => ({ i: where.get(keyOf(p))!, y: p.y })).sort((a, b) => a.i - b.i);
          // Solid runs between breaks; a dashed line bridges each cut-short gap.
          const runs: (typeof xy)[] = [];
          const bridges: [(typeof xy)[0], (typeof xy)[0]][] = [];
          xy.forEach((p, k) => {
            const prev = xy[k - 1];
            if (prev && cutsBefore[p.i] !== cutsBefore[prev.i]) {
              bridges.push([prev, p]);
              runs.push([p]);
            } else if (runs.length) runs[runs.length - 1]!.push(p);
            else runs.push([p]);
          });
          return (
            <g>
              {runs.map((run) => (
                <polyline
                  points={run.map((p) => `${at[p.i]},${sy(p.y)}`).join(' ')}
                  fill="none"
                  stroke={s.color}
                  stroke-width="2"
                  stroke-linejoin="round"
                  stroke-linecap="round"
                />
              ))}
              {bridges.map(([a, b]) => (
                <line
                  x1={at[a.i]}
                  y1={sy(a.y)}
                  x2={at[b.i]}
                  y2={sy(b.y)}
                  stroke={s.color}
                  stroke-width="2"
                  stroke-dasharray="2 4"
                  stroke-linecap="round"
                />
              ))}
              {xy.map((p) => (
                <circle cx={at[p.i]} cy={sy(p.y)} r={p.i === hover ? 5.5 : 4} fill={s.color} stroke="var(--surface)" stroke-width="2" />
              ))}
            </g>
          );
        })}
      </svg>
      {he && (
        <div
          class="tip"
          style={{
            top: '4px',
            left: tipLeftPct > 55 ? undefined : `calc(${tipLeftPct}% + 10px)`,
            right: tipLeftPct > 55 ? `calc(${100 - tipLeftPct}% + 10px)` : undefined,
          }}
        >
          <div class="t">
            {xLabel(he.x)}
            {sameDay > 1 && ` · ${he.nth + 1}번째`}
          </div>
          {lines.map(({ s, pts }) => {
            const p = pts.find((q) => q.x === he.x && q.nth === he.nth);
            return p ? (
              <div class="r">
                <span class="k" style={{ background: s.color }} />
                <b>
                  {Math.round(p.y)}
                  {ySuffix}
                </b>
                <span class="muted">{s.label}</span>
              </div>
            ) : null;
          })}
          {extra?.(he.x, he.nth) && <div class="r muted">{extra(he.x, he.nth)}</div>}
        </div>
      )}
    </div>
  );
}

export function Legend({ series }: { series: Series[] }) {
  if (series.length < 2) return null;
  return (
    <div class="legend">
      {series.map((s) => (
        <span>
          <i style={{ background: s.color }} />
          {s.label}
        </span>
      ))}
    </div>
  );
}
