/**
 * What each algorithm version shown in the app does, for the explanation that opens when its name is tapped
 * (components/AlgoTag.tsx). Plain words for patients and clinicians; the full record is docs/04 and the commits.
 * Newest version first. Update this file in the same change as a version bump.
 */
export type AlgoId = 'FPA-GEOM' | 'FPA-SYNK' | 'FPA-MUSC' | 'SC' | 'ENGINE';

export interface AlgoNote {
  title: string;
  /** What it does, in one or two sentences. */
  what: string;
  versions: readonly { v: string; date: string; text: string }[];
  /** A closing remark (limits, how it is checked). */
  note?: string;
}

