/**
 * 2-D geometry: pixel conversion, similarity (Umeyama) alignment and the
 * face-anchored coordinate frame in which all measurements are expressed.
 */
import { SIDE } from './landmarks';
import type { FrameObservation, Side, Vec2 } from './types';

export const sub = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x - b.x, y: a.y - b.y });
export const add = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x + b.x, y: a.y + b.y });
export const mul = (a: Vec2, s: number): Vec2 => ({ x: a.x * s, y: a.y * s });
export const dot = (a: Vec2, b: Vec2): number => a.x * b.x + a.y * b.y;
export const norm = (a: Vec2): number => Math.hypot(a.x, a.y);
export const dist = (a: Vec2, b: Vec2): number => Math.hypot(a.x - b.x, a.y - b.y);
export const midpoint = (a: Vec2, b: Vec2): Vec2 => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });

export function centroid(pts: readonly Vec2[]): Vec2 {
  let x = 0;
  let y = 0;
  for (const p of pts) {
    x += p.x;
    y += p.y;
  }
  return { x: x / pts.length, y: y / pts.length };
}

/** Landmarks → isotropic pixel coordinates (x·W, y·H). */
export function toPixels(obs: FrameObservation): Vec2[] {
  const n = Math.floor(obs.landmarks.length / 3);
  const out: Vec2[] = new Array(n);
  for (let i = 0; i < n; i++) out[i] = { x: obs.landmarks[3 * i]! * obs.width, y: obs.landmarks[3 * i + 1]! * obs.height };
  return out;
}

/** p' = s·R(θ)·p + t, with c = cos θ, sn = sin θ. */
export interface Similarity {
  s: number;
  c: number;
  sn: number;
  tx: number;
  ty: number;
}

/**
 * Least-squares similarity transform mapping `src` onto `dst`
 * (closed-form 2-D Umeyama / Procrustes).
 */
export function fitSimilarity(src: readonly Vec2[], dst: readonly Vec2[]): Similarity {
  if (src.length !== dst.length || src.length < 2) throw new Error('fitSimilarity needs ≥2 paired points');
  const ms = centroid(src);
  const md = centroid(dst);
  let sxx = 0;
  let sxy = 0;
  let varS = 0;
  for (let i = 0; i < src.length; i++) {
    const a = sub(src[i]!, ms);
    const b = sub(dst[i]!, md);
    sxx += a.x * b.x + a.y * b.y;
    sxy += a.x * b.y - a.y * b.x;
    varS += a.x * a.x + a.y * a.y;
  }
  const theta = Math.atan2(sxy, sxx);
  const s = Math.hypot(sxx, sxy) / varS;
  const c = Math.cos(theta);
  const sn = Math.sin(theta);
  return { s, c, sn, tx: md.x - s * (c * ms.x - sn * ms.y), ty: md.y - s * (sn * ms.x + c * ms.y) };
}

export function applySimilarity(T: Similarity, p: Vec2): Vec2 {
  return { x: T.s * (T.c * p.x - T.sn * p.y) + T.tx, y: T.s * (T.sn * p.x + T.c * p.y) + T.ty };
}

/** Eye centre = midpoint of the outer and inner canthus. */
export function eyeCenter(pts: readonly Vec2[], side: Side): Vec2 {
  return midpoint(pts[SIDE[side].eyeOuter]!, pts[SIDE[side].eyeInner]!);
}

/** Iris centres (468/473) when the 478-point topology is present, else canthal eye centres. */
export function pupilCenter(pts: readonly Vec2[], side: Side): Vec2 {
  if (pts.length >= 478) return pts[side === 'right' ? 468 : 473]!;
  return eyeCenter(pts, side);
}

/**
 * Face frame: origin at the midpoint between the pupils, x axis towards the
 * patient's LEFT pupil, y axis perpendicular pointing towards the chin, unit
 * length = interpupillary distance ("face unit", ≈ 60–65 mm in adults).
 * Pupils are used rather than canthi because the lateral canthus may sag on
 * the paralysed side, which would tilt the reference axis.
 */
export interface FaceFrame {
  origin: Vec2;
  ex: Vec2;
  ey: Vec2;
  unitPx: number;
}

export function faceFrame(pts: readonly Vec2[]): FaceFrame {
  const r = pupilCenter(pts, 'right');
  const l = pupilCenter(pts, 'left');
  const d = sub(l, r);
  const unitPx = norm(d);
  const ex = mul(d, 1 / unitPx);
  return { origin: midpoint(r, l), ex, ey: { x: -ex.y, y: ex.x }, unitPx };
}

export function toFaceCoords(frame: FaceFrame, pts: readonly Vec2[]): Vec2[] {
  return pts.map((p) => {
    const q = sub(p, frame.origin);
    return { x: dot(q, frame.ex) / frame.unitPx, y: dot(q, frame.ey) / frame.unitPx };
  });
}

/** Inverse of toFaceCoords: face-unit points back to the image pixels of `frame`. */
export function fromFaceCoords(frame: FaceFrame, pts: readonly Vec2[]): Vec2[] {
  return pts.map((q) => ({
    x: frame.origin.x + (q.x * frame.ex.x + q.y * frame.ey.x) * frame.unitPx,
    y: frame.origin.y + (q.x * frame.ex.y + q.y * frame.ey.y) * frame.unitPx,
  }));
}

/** In-plane head roll (deg) from the eye line in pixel space. */
export function rollFromEyes(pts: readonly Vec2[]): number {
  const d = sub(eyeCenter(pts, 'left'), eyeCenter(pts, 'right'));
  return (Math.atan2(d.y, d.x) * 180) / Math.PI;
}
