/**
 * Geometric measures on face-frame coordinates (units = inter-eye distance,
 * y grows towards the chin) and per-frame task measurements.
 * All formulas are specified in docs/04-algorithm-spec.md.
 */
import { dist, midpoint } from './geometry';
import { JAW_POINTS, LIP_MID_LOWER, LIP_MID_UPPER, MIDLINE, SIDE, outwardSign } from './landmarks';
import { clamp, mean } from './stats';
import type { FrameObservation, LiveTaskId, MovementTaskId, Side, SidePair, Vec2 } from './types';

type Face = readonly Vec2[];

/** Palpebral fissure height: mean distance of three upper/lower lid pairs. */
export function eyeAperture(F: Face, side: Side): number {
  return mean(SIDE[side].lidPairs.map(([u, l]) => dist(F[u]!, F[l]!)));
}

/** Mean vertical level of the upper brow contour (smaller = higher). */
export function browLevel(F: Face, side: Side): number {
  return mean(SIDE[side].brow.map((i) => F[i]!.y));
}

export function mouthCorner(F: Face, side: Side): Vec2 {
  return F[SIDE[side].mouthCorner]!;
}

export function lipCenter(F: Face): Vec2 {
  return midpoint(F[LIP_MID_UPPER]!, F[LIP_MID_LOWER]!);
}

export function midlineX(F: Face): number {
  return mean(MIDLINE.map((i) => F[i]!.x));
}

export function midfaceLevel(F: Face, side: Side): number {
  const s = SIDE[side];
  return mean([...s.ala, ...s.cheek].map((i) => F[i]!.y));
}

/** Upward displacement of nasal ala + lateral upper lip (snarl / levator). */
function levatorLift(rest: Face, expr: Face, side: Side): number {
  const s = SIDE[side];
  return mean([...s.ala, ...s.upperLip].map((i) => rest[i]!.y - expr[i]!.y));
}

export function irisDiameter(F: Face, side: Side): number {
  const [a, b, c, d] = SIDE[side].iris;
  return (dist(F[a]!, F[c]!) + dist(F[b]!, F[d]!)) / 2;
}

/** Fractional narrowing of the palpebral fissure relative to rest (≥ 0). */
export function eyeNarrowing(rest: Face, expr: Face, side: Side): number {
  return Math.max(0, 1 - eyeAperture(expr, side) / eyeAperture(rest, side));
}

/** Signed mouth-corner movement: outward (+) / inward (−) and up (+) / down (−), face units. */
/**
 * Downward movement of the chin relative to rest (face units, + = jaw lowered). The smile is asked with the teeth
 * together: an opened jaw pulls the weak mouth corner outward too, and the measure would credit it as movement.
 */
export function jawDrop(rest: Face, expr: Face): number {
  return mean(JAW_POINTS.map((i) => expr[i]!.y - rest[i]!.y));
}

export function cornerMovement(rest: Face, expr: Face, side: Side): { out: number; up: number } {
  const r = mouthCorner(rest, side);
  const e = mouthCorner(expr, side);
  return { out: (e.x - r.x) * outwardSign(side), up: r.y - e.y };
}

function cornerDisplacement(rest: Face, expr: Face, side: Side): number {
  return dist(mouthCorner(expr, side), mouthCorner(rest, side));
}

export interface FrameTaskValues {
  excursion: SidePair;
  offTarget: SidePair;
  extras: Record<string, number>;
}

const both = (f: (s: Side) => number): SidePair => ({ right: f('right'), left: f('left') });

/**
 * Measures one expression frame against the rest reference. Both inputs are
 * face-frame coordinates of the same rest-aligned space.
 *
 *  brow     : upward brow displacement                    | off-target: mouth-corner movement
 *  eyeClose : closure fraction 1 − h_expr / h_rest         | off-target: mouth-corner movement
 *  smile    : commissure excursion, up/outward components  | off-target: eye narrowing
 *  snarl    : upward lift of ala + lateral upper lip       | off-target: eye narrowing
 *  pucker   : medial shortening of corner-to-lip-centre    | off-target: eye narrowing
 */
export function measureTaskFrame(task: MovementTaskId, rest: Face, expr: Face): FrameTaskValues {
  switch (task) {
    case 'brow':
      return {
        excursion: both((s) => browLevel(rest, s) - browLevel(expr, s)),
        offTarget: both((s) => cornerDisplacement(rest, expr, s)),
        extras: {},
      };
    case 'eyeClose': {
      const gap = both((s) => eyeAperture(expr, s));
      return {
        excursion: both((s) => clamp(1 - eyeAperture(expr, s) / eyeAperture(rest, s), 0, 1)),
        offTarget: both((s) => cornerDisplacement(rest, expr, s)),
        extras: { residualGapRight: gap.right, residualGapLeft: gap.left },
      };
    }
    case 'smile':
      return {
        excursion: both((s) => {
          const { out, up } = cornerMovement(rest, expr, s);
          // Only up/outward (zygomatic) components count; passive drag and jaw drop are ignored.
          return Math.hypot(Math.max(0, out), Math.max(0, up));
        }),
        offTarget: both((s) => eyeNarrowing(rest, expr, s)),
        extras: { jawDrop: jawDrop(rest, expr) },
      };
    case 'snarl':
      return {
        excursion: both((s) => Math.max(0, levatorLift(rest, expr, s))),
        offTarget: both((s) => eyeNarrowing(rest, expr, s)),
        extras: {},
      };
    case 'pucker':
      return {
        excursion: both((s) => {
          // Relative to the lip centre, so passive drag of the whole mouth
          // towards the healthy side is not credited to the weak side.
          const dr = Math.abs(mouthCorner(rest, s).x - lipCenter(rest).x);
          const de = Math.abs(mouthCorner(expr, s).x - lipCenter(expr).x);
          return Math.max(0, dr - de);
        }),
        offTarget: both((s) => eyeNarrowing(rest, expr, s)),
        extras: {},
      };
  }
}

/**
 * The face contour beside the cheek, between the cheekbone and the jaw angle (MediaPipe face oval), per side: puffed
 * air pushes it outward.
 */
export const CHEEK_CONTOUR: Record<Side, readonly number[]> = { right: [93, 132, 58], left: [323, 361, 288] };

/** Outward bulge of the cheek contour from rest (face units, + = outward). */
export function cheekBulge(rest: Face, expr: Face, side: Side): number {
  const o = outwardSign(side);
  return mean(CHEEK_CONTOUR[side].map((i) => (expr[i]!.x - rest[i]!.x) * o));
}

/**
 * The live guide's measure (exercise mirror, SRS-RHB-022): an assessed movement as measureTaskFrame, or the cheek
 * puff (cheek contour bulge | off-target: eye narrowing — puffing should leave the eyes open).
 */
export function measureLiveTask(task: LiveTaskId, rest: Face, expr: Face): FrameTaskValues {
  if (task === 'pucker' || task === 'smile') {
    // The mouth pulled sideways (SRS-RHB-028): the lip centre's move off the upper midline, face units (+ = +x).
    const v = measureTaskFrame(task, rest, expr);
    v.extras.lipShift = lipCenter(expr).x - midlineX(expr) - (lipCenter(rest).x - midlineX(rest));
    return v;
  }
  if (task !== 'cheekPuff') return measureTaskFrame(task, rest, expr);
  return {
    excursion: both((s) => Math.max(0, cheekBulge(rest, expr, s))),
    offTarget: both((s) => eyeNarrowing(rest, expr, s)),
    extras: {},
  };
}

/** Below this share of tracked lid points an eye's landmark closure is the detection's (biased with one eye closed). */
export const LID_TRACKED_MIN = 0.5;

/**
 * FPA-GEOM 0.5.0: closure of an eye whose lid points were not tracked in this frame, from its mirror composite.
 * With only one eye closed the detection reads the closed eye about 25–32 % short (bench: real faces, half synthesis);
 * the mirror composite reads it within a few per cent. `null` = use the landmark closure.
 */
export function mirrorEyeClosure(obs: FrameObservation | undefined, side: Side): number | null {
  const m = obs?.mirrorClosure?.[side];
  if (m == null || !obs?.lidTracked || obs.lidTracked[side] >= LID_TRACKED_MIN) return null;
  return clamp(m, 0, 1);
}

/**
 * Applies mirrorEyeClosure to one eye-closure frame (excursion and residual gap). extras.mirrorLeft/Right = 1 when that
 * eye's value came from the mirror composite (0 otherwise; the task keeps the median, i.e. the majority of frames).
 */
export function withMirrorClosure(vals: FrameTaskValues, obs: FrameObservation | undefined, rest: Face): FrameTaskValues {
  const out: FrameTaskValues = { ...vals, excursion: { ...vals.excursion }, extras: { ...vals.extras, mirrorLeft: 0, mirrorRight: 0 } };
  for (const s of ['left', 'right'] as const) {
    const m = mirrorEyeClosure(obs, s);
    if (m === null) continue;
    out.excursion[s] = m;
    out.extras[s === 'left' ? 'residualGapLeft' : 'residualGapRight'] = (1 - m) * eyeAperture(rest, s);
    out.extras[s === 'left' ? 'mirrorLeft' : 'mirrorRight'] = 1;
  }
  return out;
}

/** Scalar used to find the peak of a movement; side-agnostic to avoid bias. */
export const taskSignal = (v: FrameTaskValues): number => v.excursion.right + v.excursion.left;

/** Whether the task's excursion is a distance (convertible to mm). */
export const isMetricTask = (task: MovementTaskId): boolean => task !== 'eyeClose';
