/**
 * Use mode of this device (ui/role.ts) and the institution PIN that guards it.
 *
 * The mode belongs to the device, not to a record: on a clinic device every research subject's records (subjects.ts)
 * open in the same clinician mode. Leaving patient mode for clinician or researcher mode asks for the institution PIN,
 * so a patient holding a pilot device cannot open estimated grades, clinician ratings or other subjects' records by
 * accident (decision guide §6). The PIN is made the first time a non-patient mode is chosen on the device and is kept
 * only as a salted PBKDF2 hash, with the same slow-down on wrong tries as the app lock (lock.ts).
 */
import { checkSecret, hashSecret, recordAttempt, waitMs } from './lock';
import type { UserRole } from './types';

const ROLE_KEY = 'fpc.role.v1';
const PIN_KEY = 'fpc.modepin.v1';
const ATTEMPTS_KEY = 'fpc.modepin.attempts.v1';

/** 4–8 digits. */
export const MODE_PIN = /^\d{4,8}$/;

const ROLES: readonly UserRole[] = ['patient', 'clinician', 'researcher'];

/** The mode chosen on this device, or null if none was chosen yet (older installs keep it in the profile). */
export function deviceRole(): UserRole | null {
  try {
    const v = localStorage.getItem(ROLE_KEY);
    return v && (ROLES as readonly string[]).includes(v) ? (v as UserRole) : null;
  } catch {
    return null;
  }
}

export function setDeviceRole(role: UserRole): void {
  try {
    localStorage.setItem(ROLE_KEY, role);
  } catch {
    /* private mode: the profile still carries the role */
  }
}

export function hasModePin(): boolean {
  try {
    return !!localStorage.getItem(PIN_KEY);
  } catch {
    return false;
  }
}

export async function setModePin(pin: string): Promise<void> {
  if (!MODE_PIN.test(pin)) throw new Error('PIN must be 4-8 digits');
  const h = await hashSecret(pin);
  localStorage.setItem(PIN_KEY, JSON.stringify(h));
  recordAttempt(true, Date.now(), ATTEMPTS_KEY);
}

/** 'wait' = too many wrong tries, see modePinWaitMs(). */
export async function checkModePin(pin: string, now = Date.now()): Promise<'ok' | 'wrong' | 'wait'> {
  if (waitMs(now, ATTEMPTS_KEY) > 0) return 'wait';
  let stored;
  try {
    const v = localStorage.getItem(PIN_KEY);
    stored = v ? JSON.parse(v) : undefined;
  } catch {
    stored = undefined;
  }
  const ok = await checkSecret(pin, stored);
  recordAttempt(ok, now, ATTEMPTS_KEY);
  return ok ? 'ok' : 'wrong';
}

export const modePinWaitMs = (now = Date.now()): number => waitMs(now, ATTEMPTS_KEY);

/** Forgets the mode and the PIN (all data deleted on a device without research subjects). */
export function clearDeviceMode(): void {
  try {
    for (const k of [ROLE_KEY, PIN_KEY, ATTEMPTS_KEY]) localStorage.removeItem(k);
  } catch {
    /* private mode */
  }
}
