/**
 * What a missing movement costs (FPA-COV). When uploaded photos cover only some tasks (e.g. rest and a smile), the
 * Sunnybrook and House–Brackmann estimates are known only as a range. The range is found by trying every plausible
 * value of each missing task (movement ratio 0, 0.25 … 1; no synkinesis assumed), and the same is done after
 * "adding" each missing task, so the app can say which extra photo narrows the estimate most.
 * Pure and deterministic; uses the unchanged scoring rules (scoring.ts).
 */
import { computeScores, isScoredTask, voluntaryGrade } from './scoring';
import { MOVEMENT_TASKS, type AnalysisResult, type MovementTaskId, type TaskMeasurement } from './types';

export const COVER_RATIOS: readonly number[] = [0, 0.25, 0.5, 0.75, 1];

export interface CoverageGain {
  task: MovementTaskId;
  /** Mean width of the composite range once this task is measured (over its possible values). */
  compositeWidth: number;
  hbWidth: number;
}

export interface Coverage {
  missing: MovementTaskId[];
  composite: [number, number];
  hb: [number, number];
  /** Missing tasks, the most useful first. */
  gain: CoverageGain[];
}

function stand(task: MovementTaskId, ratio: number): TaskMeasurement {
  return {
    task,
    excursion: { left: ratio, right: 1 },
    ratio,
    offTarget: { left: 0, right: 0 },
    synkinesisIndex: 0,
    grade: voluntaryGrade(ratio),
    synkinesisGrade: 0,
    reliable: true,
    extras: task === 'eyeClose' ? { residualGapLeft: 0, residualGapRight: 0 } : {},
    quality: {
      framesTotal: 0,
      framesValid: 0,
      framesUsed: 0,
      issueCounts: {},
      medianAbsYaw: 0,
      medianAbsPitch: 0,
      medianAbsRoll: 0,
      alignmentResidual: 0,
    },
  };
}

function* combos(tasks: readonly MovementTaskId[]): Generator<Map<MovementTaskId, number>> {
  if (tasks.length === 0) {
    yield new Map();
    return;
  }
  const [head, ...rest] = tasks;
  for (const v of COVER_RATIOS) for (const m of combos(rest)) yield new Map([[head!, v], ...m]);
}

export function scoreCoverage(r: AnalysisResult): Coverage | null {
  if (!r.rest) return null;
  const scored = MOVEMENT_TASKS.filter(isScoredTask);
  const known = new Map<MovementTaskId, TaskMeasurement>();
  for (const t of scored) if (r.tasks[t]?.reliable) known.set(t, r.tasks[t]!);
  const missing = scored.filter((t) => !known.has(t));
  const range = (free: readonly MovementTaskId[], fixed: Map<MovementTaskId, number>) => {
    let [cLo, cHi, hLo, hHi] = [Infinity, -Infinity, Infinity, -Infinity];
    for (const m of combos(free)) {
      const tasks: Partial<Record<MovementTaskId, TaskMeasurement>> = {};
      for (const t of scored) {
        const v = m.get(t) ?? fixed.get(t);
        tasks[t] = v !== undefined ? stand(t, v) : known.get(t)!;
      }
      const s = computeScores(r.rest!, tasks as Parameters<typeof computeScores>[1], r.affectedSide, r.mmPerUnit);
      cLo = Math.min(cLo, s.composite);
      cHi = Math.max(cHi, s.composite);
      hLo = Math.min(hLo, s.houseBrackmann.grade);
      hHi = Math.max(hHi, s.houseBrackmann.grade);
    }
    return { composite: [cLo, cHi] as [number, number], hb: [hLo, hHi] as [number, number] };
  };
  const now = range(missing, new Map());
  const gain = missing
    .map((task) => {
      const others = missing.filter((t) => t !== task);
      const w = COVER_RATIOS.map((v) => range(others, new Map([[task, v]])));
      const mean = (xs: number[]) => xs.reduce((a, b) => a + b, 0) / xs.length;
      return {
        task,
        compositeWidth: mean(w.map((x) => x.composite[1] - x.composite[0])),
        hbWidth: mean(w.map((x) => x.hb[1] - x.hb[0])),
      };
    })
    .sort((a, b) => a.compositeWidth + 10 * a.hbWidth - (b.compositeWidth + 10 * b.hbWidth));
  return { missing, composite: now.composite, hb: now.hb, gain };
}
