import { useEffect, useState } from 'preact/hooks';
import { ALGORITHM_ID, ALGORITHM_VERSION, SCORING_VERSION } from '../../core';
import { FEATURES, PROFILE } from '../../config';
import { CONSENT_VERSION, INTENDED_USE } from '../../data/consent';
import { download, exportCsv } from '../../data/export';
import { APP_INFO } from '../../data/records';
import { countSnapshots, deleteAllSnapshots } from '../../data/snapshots';
import { actions, getState, useApp } from '../../data/store';
import { DOSE_VERSION } from '../../rehab/dose';
import { PLANNER_VERSION } from '../../rehab/planner';
import MODEL_LOCK from '../../vision/model-lock.json';
import { AppBar, Notice, Segmented } from '../components/common';
import { ImportBackup } from '../components/ImportBackup';
import { getTextSize, getTheme, setTextSize, setTheme, type TextSize, type ThemePref } from '../theme';
import { DeviceCare, backupNow } from '../components/KeepSafe';
import { AppLockSettings } from '../components/AppLockSettings';
import { ReminderSettings } from '../components/ReminderSettings';
import { LICENSED_SCALES } from '../../rehab/checkin';
import { Icon } from '../icons';
import { ProfileFields, type ProfileDraft } from './Onboarding';
import { ROLE_LABEL, availableRoles, roleOf, showClinicalTools } from '../role';
import { ModePinForm } from '../components/ModePin';
import { ResearchConsentCard } from '../components/ResearchConsent';
import { RESEARCH_CONSENT_VERSION, canGiveResearchData, researchConsentOf } from '../../data/consent';
import { setDeviceRole } from '../../data/mode';
import type { UserRole } from '../../data/types';
import { DEFAULT_METHOD, METHOD_LABEL, METHOD_VERSION, type TrackMethod } from '../../vision/method';
import { AlgoTag } from '../components/AlgoTag';

declare const __MP_VERSION__: string;

export function Settings() {
  const [photoCount, setPhotoCount] = useState(0);
  useEffect(() => {
    countSnapshots().then(setPhotoCount, () => setPhotoCount(0));
  }, []);
  const { profile, sessions } = useApp();
  const [draft, setDraft] = useState<ProfileDraft | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);
  const [theme, setThemeState] = useState<ThemePref>(getTheme);
  const [textSize, setTextSizeState] = useState<TextSize>(getTextSize);
  /** Mode waiting for the institution PIN, or 'change' while a new PIN is being set. */
  const [pinFor, setPinFor] = useState<UserRole | 'change' | null>(null);
  if (!profile) return null;
  const stamp = new Date().toISOString().slice(0, 10);
  const applyRole = async (role: UserRole) => {
    setDeviceRole(role);
    setPinFor(null);
    await actions.saveProfile({ ...profile, role });
  };

  return (
    <>
      <AppBar title="설정" />
      <main class="main">
        {availableRoles().length > 1 && (
          <>
            <div class="section-title">사용 모드</div>
            <div class="card tight">
              <Segmented
                label="누가 쓰나요"
                value={pinFor && pinFor !== 'change' ? pinFor : roleOf(profile)}
                onChange={(role: UserRole) => {
                  // Leaving patient mode asks for the institution PIN; any other change applies at once.
                  if (role === roleOf(profile)) setPinFor(null);
                  else if (role !== 'patient' && roleOf(profile) === 'patient') setPinFor(role);
                  else void applyRole(role);
                }}
                options={availableRoles().map((r) => ({ value: r, label: ROLE_LABEL[r] }))}
              />
              {pinFor && pinFor !== 'change' && (
                <ModePinForm label={ROLE_LABEL[pinFor]} onOk={() => applyRole(pinFor)} onCancel={() => setPinFor(null)} />
              )}
              {!pinFor && (
                <span class="xsmall muted">
                  {roleOf(profile) === 'patient'
                    ? '평가·재활·경과 중심으로 보여 줍니다.'
                    : `${
                        roleOf(profile) === 'clinician'
                          ? '추정 등급(HB·Sunnybrook), 임상가 평가 입력, 연구 피험자, 일치도를 함께 보여 줍니다.'
                          : '의료진 기능에 개발·검수 도구를 더해 보여 줍니다.'
                      } 환자에게 기기를 건넬 때는 환자 모드로 바꾸세요. 다시 바꿀 때 기관 PIN을 묻습니다.`}
                </span>
              )}
              {roleOf(profile) !== 'patient' &&
                (pinFor === 'change' ? (
                  <ModePinForm label={ROLE_LABEL[roleOf(profile)]} make onOk={() => setPinFor(null)} onCancel={() => setPinFor(null)} />
                ) : (
                  !pinFor && (
                    <button class="btn sm ghost" style={{ alignSelf: 'flex-start' }} onClick={() => setPinFor('change')}>
                      기관 PIN 바꾸기
                    </button>
                  )
                ))}
              {roleOf(profile) === 'patient' && FEATURES.estimatedScales && (
                <label class="check" style={{ padding: 0 }}>
                  <input
                    type="checkbox"
                    checked={!!profile.showScales}
                    onChange={(e) => actions.saveProfile({ ...profile, showScales: (e.target as HTMLInputElement).checked })}
                  />
                  <span class="small">추정 등급(HB·Sunnybrook)도 보기 — 검증 전 참고값, 의료진 판단이 우선</span>
                </label>
              )}
            </div>
          </>
        )}

        <div class="section-title">내 정보</div>
        <div class="card">
          {draft ? (
            <>
              <ProfileFields value={draft} onChange={setDraft} />
              {draft.affectedSide !== profile.affectedSide && (
                <Notice tone="warn">
                  <span class="small">마비된 쪽을 바꾸면 이후 평가부터 적용됩니다. 이전 기록은 기록 당시 설정을 유지합니다.</span>
                </Notice>
              )}
              <div class="row">
                <button class="btn grow" onClick={() => setDraft(null)}>
                  취소
                </button>
                <button
                  class="btn primary grow"
                  onClick={async () => {
                    await actions.saveProfile({ ...profile, ...draft });
                    setDraft(null);
                  }}
                >
                  저장
                </button>
              </div>
            </>
          ) : (
            <button
              class="list-item"
              onClick={() =>
                setDraft({
                  affectedSide: profile.affectedSide,
                  onsetDate: profile.onsetDate,
                  etiology: profile.etiology,
                  nickname: profile.nickname,
                  birthYear: profile.birthYear,
                })
              }
            >
              <div class="grow">
                <div>{profile.nickname || '이름 없음'}</div>
                <div class="small ink2">
                  마비 쪽 {profile.affectedSide === 'left' ? '왼쪽' : '오른쪽'} · 발병일 {profile.onsetDate}
                </div>
              </div>
              <Icon name="chev" class="chev" />
            </button>
          )}
        </div>

        {FEATURES.rehab !== 'off' && (
          <>
            <div class="section-title">운동·평가 알림</div>
            <ReminderSettings profile={profile} />

            <div class="section-title">환자 설문 (시험)</div>
            <div class="card">
              <label class="check" style={{ padding: 0 }}>
                <input
                  id="checkin-enabled"
                  type="checkbox"
                  checked={!!profile.checkin?.enabled}
                  onChange={(e) => actions.saveProfile({ ...profile, checkin: { enabled: (e.target as HTMLInputElement).checked } })}
                />
                <span>
                  이번 주 체크 <span class="small muted">— 일주일에 한 번, 운동을 얼마나 했는지·못 한 이유·불편함을 묻습니다(약 1분)</span>
                </span>
              </label>
              <p class="xsmall muted" style={{ margin: 0 }}>
                앱 자체 문항이며 검증된 척도가 아닙니다. 답은 의료진용 요약과 내보내기에 들어갑니다. 끄면 질문과 요약 표시가 멈추고, 이미 한
                답은 이 기기에 남습니다. 검증된 한국어판 {LICENSED_SCALES.map((l) => l.id).join('·')}는 저작자 허락을 받으면 넣을 수
                있습니다.
              </p>
            </div>
          </>
        )}

        <div class="section-title">사용 환경</div>
        <div class="card">
          <label class="check" style={{ padding: 0 }}>
            <input
              type="checkbox"
              checked={profile.voiceGuide}
              onChange={(e) => actions.saveProfile({ ...profile, voiceGuide: (e.target as HTMLInputElement).checked })}
            />
            <span>
              음성 안내 <span class="small muted">— 평가·운동 중 지시를 읽어 줍니다</span>
            </span>
          </label>
          <div class="field">
            <span>얼굴 그림 방향</span>
            <Segmented
              label="얼굴 그림 방향"
              value={profile.viewMode}
              onChange={(v) => actions.saveProfile({ ...profile, viewMode: v })}
              options={[
                { value: 'mirror', label: '거울처럼' },
                { value: 'clinical', label: '마주 본 모습(임상)' },
              ]}
            />
          </div>
          <div class="field">
            <span>글자 크기</span>
            <Segmented
              label="글자 크기"
              value={textSize}
              onChange={(v) => {
                setTextSize(v);
                setTextSizeState(v);
              }}
              options={[
                { value: 'normal', label: '보통' },
                { value: 'large', label: '크게' },
                { value: 'xlarge', label: '아주 크게' },
              ]}
            />
          </div>
          <div class="field">
            <span>화면 테마</span>
            <Segmented
              label="화면 테마"
              value={theme}
              onChange={(v) => {
                setTheme(v);
                setThemeState(v);
              }}
              options={[
                { value: 'light', label: '밝게' },
                { value: 'dark', label: '어둡게' },
                { value: 'system', label: '기기 설정' },
              ]}
            />
          </div>
        </div>

        <div class="section-title">앱 설치·기록 보관</div>
        <DeviceCare />

        <div class="section-title">앱 잠금</div>
        <AppLockSettings />

        {PROFILE === 'research' && (
          <>
            <div class="section-title">측정 방식 (연구용 시험)</div>
            <div class="card">
              <div class="field">
                <span>얼굴 움직임을 읽는 방식</span>
                <Segmented
                  label="측정 방식"
                  value={profile.trackMethod ?? DEFAULT_METHOD}
                  onChange={(v) => void actions.saveProfile({ ...profile, trackMethod: v as TrackMethod })}
                  options={(Object.keys(METHOD_LABEL) as TrackMethod[]).map((m) => ({ value: m, label: METHOD_LABEL[m] }))}
                />
              </div>
              <ul class="xsmall muted" style={{ margin: '6px 0 0', paddingLeft: '18px' }}>
                <li>기본: 지금 앱의 방식. 입 오므리기만 더 촘촘하게 따라갑니다.</li>
                <li>이전: v0.5.0과 같은 방식(오므리기도 다른 동작과 같게).</li>
                <li>
                  SEA-RAFT 혼합: 눈 감기는 기본 방식, 이마·웃기·코·오므리기는 SEA-RAFT 광류로 잽니다. 처음 쓸 때 모델과 실행 파일 약 110
                  MB를 받으니 Wi-Fi에서 켜 주세요. 폰의 GPU(WebGPU)로 계산하고, GPU를 못 쓰는 폰에서는 한 쌍에 수십 초 걸릴 수 있습니다(영상
                  평가는 32쌍). 분석이 끝나면 걸린 시간이 결과에 나옵니다. 사진은 서버로 보내지 않고 이 폰 안에서 계산합니다.
                </li>
              </ul>
              <p class="xsmall muted" style={{ margin: '6px 0 0' }}>
                결과에는 쓴 방식이 버전으로 남습니다(v{METHOD_VERSION.v060} · v{METHOD_VERSION.v050} · v{METHOD_VERSION.raft},{' '}
                <AlgoTag id="FPA-GEOM" version={METHOD_VERSION[profile.trackMethod ?? DEFAULT_METHOD]} label="버전별 설명" />
                ). 방식이 다른 평가끼리 비교하면 결과 화면이 알려 줍니다. 예비 연구 기록은 기본 방식으로 찍어 주세요.
              </p>
            </div>
          </>
        )}

        <div class="section-title">평가 사진</div>
        <div class="card">
          <label class="check" style={{ padding: 0 }}>
            <input
              type="checkbox"
              checked={!!profile.savePhotos}
              onChange={async (e) => {
                const on = (e.target as HTMLInputElement).checked;
                if (on && !confirm(PHOTO_CONSENT)) {
                  (e.target as HTMLInputElement).checked = false;
                  return;
                }
                if (
                  !on &&
                  photoCount > 0 &&
                  confirm(`저장된 사진(${photoCount}회 평가분)도 지울까요? 취소하면 사진은 남고 새로 찍지 않습니다.`)
                ) {
                  await deleteAllSnapshots();
                  setPhotoCount(0);
                }
                await actions.saveProfile({ ...profile, savePhotos: on });
              }}
            />
            <span>
              평가 사진 저장 <span class="small muted">— 동작마다 표정을 유지한 순간 1장씩, 이 폰에만</span>
            </span>
          </label>
          <p class="xsmall muted" style={{ margin: '6px 0 0' }}>
            결과의 ‘얼굴 움직임 모양’에서 선 그림 대신 사진으로 볼 수 있습니다. 사진은 서버로 보내지 않고, 전체 기록 내보내기(JSON·CSV)에도
            들어가지 않습니다. 연구 참여에서 사진까지 동의한 경우에만 암호화한 연구 자료 꾸러미에 들어갑니다.
          </p>
          {photoCount > 0 && (
            <button
              class="btn sm block"
              style={{ marginTop: '8px' }}
              onClick={async () => {
                if (!confirm(`저장된 사진(${photoCount}회 평가분)을 모두 지웁니다. 측정 기록은 남습니다.`)) return;
                await deleteAllSnapshots();
                setPhotoCount(0);
              }}
            >
              저장된 사진 모두 지우기 ({photoCount}회 평가분)
            </button>
          )}
        </div>

        {FEATURES.researchTools && (
          <>
            <div class="section-title">연구 참여</div>
            <ResearchConsentCard profile={profile} />
            <div class="card tight">
              <div class="list">
                <a class="list-item" href="#/package">
                  <Icon name="shield" />
                  <div class="grow">
                    연구 자료 꾸러미 만들기 (암호화)
                    <div class="xsmall muted">
                      {canGiveResearchData(researchConsentOf(profile))
                        ? '동의한 항목만 담아 연구 PC로 옮길 파일'
                        : '연구 참여 동의를 기록하면 만들 수 있습니다'}
                    </div>
                  </div>
                  <Icon name="chev" class="chev" />
                </a>
                {showClinicalTools(profile) && (
                  <a class="list-item" href="#/collect">
                    <Icon name="clipboard" />
                    <div class="grow">
                      연구 자료 모으기 (연구 PC)
                      <div class="xsmall muted">꾸러미를 열어 확인하고 피험자별로 합쳐 분석 도구용으로 저장</div>
                    </div>
                    <Icon name="chev" class="chev" />
                  </a>
                )}
              </div>
            </div>
          </>
        )}

        <div class="section-title">데이터</div>
        <p class="xsmall muted" style={{ margin: '0 4px 6px' }}>
          내보낸 파일에는 이름과 사진은 없지만 건강 정보(측정값·발병일)가 들어 있습니다. 믿을 수 있는 곳에만 보관하고 전달하세요.
        </p>
        <div class="card tight">
          <div class="list">
            <button class="list-item" onClick={backupNow}>
              <Icon name="download" />
              <div class="grow">
                전체 기록 내보내기 (JSON)
                <div class="xsmall muted">백업 파일 — 무결성 해시·버전 정보 포함, 이름·사진 제외</div>
              </div>
            </button>
            <button
              class="list-item"
              onClick={() => download(`facial-palsy-${stamp}.csv`, exportCsv(getState()), 'text/csv;charset=utf-8')}
            >
              <Icon name="download" />
              <div class="grow">
                평가 요약 내보내기 (CSV)
                <div class="xsmall muted">평가 1회당 1행, 임상가 평가 포함</div>
              </div>
            </button>
            <ImportBackup />
            {showClinicalTools(profile) && (
              <a class="list-item" href="#/subjects">
                <Icon name="clipboard" />
                <div class="grow">
                  연구 피험자 (외래 연구 기기)
                  <div class="xsmall muted">가명 코드별로 기록을 따로 저장·전환</div>
                </div>
                <Icon name="chev" class="chev" />
              </a>
            )}
            {showClinicalTools(profile) && (
              <a class="list-item" href="#/research">
                <Icon name="flask" />
                <div class="grow">
                  연구 도구
                  <div class="xsmall muted">임상가 평가 입력, 일치도(ICC·κ), 사진·영상 분석</div>
                </div>
                <Icon name="chev" class="chev" />
              </a>
            )}
            {FEATURES.demo && (
              <a class="list-item" href="#/cases">
                <Icon name="image" />
                <div class="grow">
                  실제 사진 사례
                  <div class="xsmall muted">공개 라이선스 안면마비 사진 분석·경과 보기</div>
                </div>
                <Icon name="chev" class="chev" />
              </a>
            )}
            {FEATURES.demo && (
              <button
                class="list-item"
                disabled={busy}
                onClick={async () => {
                  if (!confirm('현재 기록을 모두 지우고 데모 데이터로 바꿉니다. 계속할까요?')) return;
                  setBusy(true);
                  await actions.loadDemo();
                  setBusy(false);
                }}
              >
                <Icon name="chart" />
                <div class="grow">
                  데모 데이터로 교체
                  <div class="xsmall muted">합성 데이터 10회 평가 · 기존 기록 삭제</div>
                </div>
              </button>
            )}
          </div>
        </div>
        <div class="card tight">
          {!confirmDelete ? (
            <button class="btn danger block" onClick={() => setConfirmDelete(true)}>
              <Icon name="trash" /> 모든 데이터 삭제
            </button>
          ) : (
            <>
              <Notice tone="danger">
                <span class="small">
                  평가 {sessions.length}건과 운동 기록, 프로필이 이 기기에서 영구히 삭제됩니다. 필요하면 먼저 내보내기 하세요.
                </span>
              </Notice>
              <div class="row">
                <button class="btn grow" onClick={() => setConfirmDelete(false)}>
                  취소
                </button>
                <button
                  class="btn grow"
                  style={{ background: 'var(--critical)', color: '#fff' }}
                  onClick={async () => {
                    await actions.deleteAll();
                    location.hash = '/';
                  }}
                >
                  영구 삭제
                </button>
              </div>
            </>
          )}
        </div>

        <div class="section-title">정보</div>
        <details class="card tight">
          <summary class="ink2" style={{ fontWeight: 600 }}>
            사용 목적과 소프트웨어 구성
          </summary>
          <p class="small">{INTENDED_USE}</p>
          <table class="data">
            <tbody>
              <tr>
                <td>앱</td>
                <td>
                  v{APP_INFO.version} ({PROFILE})
                </td>
              </tr>
              <tr>
                <td>빌드</td>
                <td class="xsmall">{APP_INFO.build}</td>
              </tr>
              <tr>
                <td>측정 알고리즘</td>
                <td>
                  <AlgoTag id="FPA-GEOM" version={ALGORITHM_VERSION} label={`${ALGORITHM_ID} v${ALGORITHM_VERSION}`} />
                </td>
              </tr>
              <tr>
                <td>점수 매핑</td>
                <td>
                  <AlgoTag id="SC" version={SCORING_VERSION} />
                </td>
              </tr>
              <tr>
                <td>재활 계획 규칙</td>
                <td>{PLANNER_VERSION}</td>
              </tr>
              <tr>
                <td>운동 양 조절</td>
                <td>{DOSE_VERSION}</td>
              </tr>
              <tr>
                <td>동의 문서</td>
                <td>
                  {CONSENT_VERSION}
                  {FEATURES.researchTools && ` · 연구 ${RESEARCH_CONSENT_VERSION}`}
                </td>
              </tr>
              <tr>
                <td>얼굴 인식 (SOUP)</td>
                <td class="xsmall">MediaPipe Tasks Vision {__MP_VERSION__}</td>
              </tr>
              <tr>
                <td>모델</td>
                <td class="xsmall">{MODEL_LOCK.name}</td>
              </tr>
              <tr>
                <td>모델 SHA-256</td>
                <td class="mono">{MODEL_LOCK.sha256}</td>
              </tr>
            </tbody>
          </table>
          <p class="xsmall muted">연구용 프로토타입입니다. 의료기기로 허가받지 않았습니다.</p>
        </details>
      </main>
    </>
  );
}

